// v3tc01_incremental_migration / ex1 - reference solution (author only).

export function asRecord(value: unknown): Record<string, unknown> | undefined {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return undefined;
  }
  return value as Record<string, unknown>;
}

export function readString(value: unknown, key: string): string | undefined {
  const record = asRecord(value);
  if (record === undefined) return undefined;
  const found = record[key];
  return typeof found === "string" ? found : undefined;
}

export function readNumber(value: unknown, key: string): number | undefined {
  const record = asRecord(value);
  if (record === undefined) return undefined;
  const found = record[key];
  return typeof found === "number" && Number.isFinite(found) ? found : undefined;
}

export function requireString(
  value: unknown,
  key: string,
  where: string,
): string {
  const found = readString(value, key);
  if (found === undefined) {
    throw new Error(`${where}: expected string at "${key}"`);
  }
  return found;
}

// v3tc01_incremental_migration / ex2 - reference solution (author only).

export interface CartApi {
  addItem(sku: string, quantity: number): void;
  total(): number;
}

type LegacyCart = {
  add_item(sku: string, quantity: number): void;
  get_total(): unknown;
};

function isCallable(value: object, name: string): boolean {
  return (
    name in value &&
    typeof (value as Record<string, unknown>)[name] === "function"
  );
}

export function createCartAdapter(legacy: unknown): CartApi {
  if (
    typeof legacy !== "object" ||
    legacy === null ||
    !isCallable(legacy, "add_item") ||
    !isCallable(legacy, "get_total")
  ) {
    throw new Error("legacy-cart: incompatible module shape");
  }
  // Checked immediately above; this one cast is what the adapter exists for.
  const module = legacy as LegacyCart;

  return {
    addItem(sku: string, quantity: number): void {
      if (!Number.isInteger(quantity) || quantity <= 0) {
        throw new Error("legacy-cart: quantity must be a positive integer");
      }
      module.add_item(sku, quantity);
    },
    total(): number {
      const raw = module.get_total();
      if (typeof raw !== "number" || !Number.isFinite(raw)) {
        throw new Error("legacy-cart: get_total returned a non-number");
      }
      return raw;
    },
  };
}

// v3tc01_incremental_migration / ex3 - reference solution (author only).

export function firstMatching<T>(
  items: readonly T[],
  predicate: (item: T, index: number) => boolean,
): T | undefined {
  for (let index = 0; index < items.length; index += 1) {
    const item = items[index] as T;
    if (predicate(item, index)) return item;
  }
  return undefined;
}

export function mustFind<T>(
  items: readonly T[],
  predicate: (item: T, index: number) => boolean,
  label: string,
): T {
  for (let index = 0; index < items.length; index += 1) {
    const item = items[index] as T;
    if (predicate(item, index)) return item;
  }
  throw new Error(`no match for ${label}`);
}

export function at<T>(items: readonly T[], index: number): T | undefined {
  if (!Number.isInteger(index)) return undefined;
  const resolved = index < 0 ? items.length + index : index;
  if (resolved < 0 || resolved >= items.length) return undefined;
  return items[resolved];
}

