// v3tc01_incremental_migration / ex4 - reference solution (author only).

export type RatchetViolation =
  | { kind: "increase"; file: string; was: number; now: number }
  | { kind: "unlisted"; file: string; now: number };

export interface RatchetReport {
  ok: boolean;
  violations: RatchetViolation[];
  improvements: { file: string; was: number; now: number }[];
  nextBaseline: Record<string, number>;
}

export function ratchet(
  baseline: Readonly<Record<string, number>>,
  current: Readonly<Record<string, number>>,
): RatchetReport {
  const violations: RatchetViolation[] = [];
  const improvements: { file: string; was: number; now: number }[] = [];
  const kept: [string, number][] = [];

  for (const [file, now] of Object.entries(current)) {
    const was = baseline[file];
    if (was === undefined) {
      if (now > 0) violations.push({ kind: "unlisted", file, now });
    } else if (now > was) {
      violations.push({ kind: "increase", file, was, now });
    } else if (now < was) {
      improvements.push({ file, was, now });
    }
    if (now > 0) kept.push([file, now]);
  }

  const byFile = (a: { file: string }, b: { file: string }) =>
    a.file < b.file ? -1 : a.file > b.file ? 1 : 0;
  violations.sort(byFile);
  improvements.sort(byFile);
  kept.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));

  return {
    ok: violations.length === 0,
    violations,
    improvements,
    nextBaseline: Object.fromEntries(kept),
  };
}

// v3tc01_incremental_migration / ex5 - reference solution (author only).

export interface Suppression {
  line: number;
  directive: "ts-expect-error" | "ts-ignore";
  owner: string | null;
  reason: string;
}

const DIRECTIVE = /^\s*\/\/\s*@(ts-expect-error|ts-ignore)\b(.*)$/;
const OWNER = /owner:@([A-Za-z0-9._-]+)/;

export function parseSuppressions(source: string): Suppression[] {
  const found: Suppression[] = [];
  const lines = source.split("\n");
  for (let index = 0; index < lines.length; index += 1) {
    const match = DIRECTIVE.exec(lines[index] ?? "");
    if (!match) continue;
    const directive = match[1] as "ts-expect-error" | "ts-ignore";
    const rest = match[2] ?? "";
    const ownerMatch = OWNER.exec(rest);
    const reason = rest
      .replace(OWNER, "")
      .replace(/^[\s\-—]+/, "")
      .trim();
    found.push({
      line: index + 1,
      directive,
      owner: ownerMatch ? (ownerMatch[1] as string) : null,
      reason,
    });
  }
  return found;
}

export function auditSuppressions(source: string): string[] {
  const diagnostics: string[] = [];
  for (const suppression of parseSuppressions(source)) {
    const { line } = suppression;
    if (suppression.directive === "ts-ignore") {
      diagnostics.push(`line ${line}: use @ts-expect-error instead of @ts-ignore`);
    }
    if (suppression.reason.length === 0) {
      diagnostics.push(`line ${line}: suppression needs a reason`);
    }
    if (suppression.owner === null) {
      diagnostics.push(`line ${line}: suppression needs owner:@handle`);
    }
  }
  return diagnostics;
}

// v3tc01_incremental_migration / ex6 - reference solution (author only).

export interface JsDocParam {
  name: string;
  type: string;
  optional: boolean;
  defaultValue: string | null;
  description: string;
}

export interface JsDocSignature {
  params: JsDocParam[];
  returns: string | null;
}

function stripDecoration(block: string): string[] {
  return block
    .split("\n")
    .map((line) =>
      line.replace(/^\s*\/?\*+\/?\s?/, "").replace(/\s*\*\/\s*$/, "").trim(),
    )
    .filter((line) => line.length > 0);
}

/** Returns the balanced `{...}` group at `start` plus the index after it. */
function readBraced(
  text: string,
  start: number,
): { inner: string; end: number } | null {
  if (text[start] !== "{") return null;
  let depth = 0;
  for (let i = start; i < text.length; i += 1) {
    if (text[i] === "{") depth += 1;
    else if (text[i] === "}") {
      depth -= 1;
      if (depth === 0) {
        return { inner: text.slice(start + 1, i).trim(), end: i + 1 };
      }
    }
  }
  return null;
}

const NAME = /^\[?([A-Za-z_$][\w$.]*)(?:=([^\]]*))?\]?/;

export function parseJsDoc(block: string): JsDocSignature {
  const params: JsDocParam[] = [];
  let returns: string | null = null;

  for (const line of stripDecoration(block)) {
    const tag = /^@(param|returns|return)\b\s*/.exec(line);
    if (!tag) continue;
    const braced = readBraced(line, tag[0].length);
    if (!braced) continue;

    if (tag[1] !== "param") {
      returns = braced.inner;
      continue;
    }

    const rest = line.slice(braced.end).trimStart();
    const name = NAME.exec(rest);
    if (!name) continue;
    params.push({
      name: name[1] as string,
      type: braced.inner,
      optional: rest.startsWith("["),
      defaultValue: name[2] === undefined ? null : name[2],
      description: rest
        .slice(name[0].length)
        .replace(/^[\s\-—]+/, "")
        .trim(),
    });
  }

  return { params, returns };
}

