// v3tc01_incremental_migration / ex7 - reference solution (author only).

export interface FileStat {
  path: string;
  lines: number;
  typed: boolean;
  anyCount: number;
  importedBy: number;
}

export interface MigrationSummary {
  totalFiles: number;
  typedFiles: number;
  totalLines: number;
  typedLines: number;
  percentTyped: number;
}

export function summarize(files: readonly FileStat[]): MigrationSummary {
  let typedFiles = 0;
  let totalLines = 0;
  let typedLines = 0;
  for (const file of files) {
    totalLines += file.lines;
    if (file.typed) {
      typedFiles += 1;
      typedLines += file.lines;
    }
  }
  const percentTyped =
    totalLines === 0 ? 0 : Math.round((typedLines / totalLines) * 1000) / 10;
  return {
    totalFiles: files.length,
    typedFiles,
    totalLines,
    typedLines,
    percentTyped,
  };
}

function scoreOf(file: FileStat): number {
  return file.importedBy * 10 - file.anyCount * 2 - Math.floor(file.lines / 50);
}

export function nextTargets(
  files: readonly FileStat[],
  count: number,
): string[] {
  if (count <= 0) return [];
  return files
    .filter((file) => !file.typed)
    .map((file) => ({ path: file.path, score: scoreOf(file) }))
    .sort((a, b) => b.score - a.score || (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
    .slice(0, count)
    .map((entry) => entry.path);
}

