## challenge — the migration gate (moderate)

Edit `challenge/solution.ts`. Everything in this sector so far has been one
rule. CI needs all of them at once, in one report, with one exit code.

```ts
export interface FileReport {
  path: string;
  anyCount: number;
  suppressions: number;
  owner: string | null;
}

export interface Baselines {
  any: Readonly<Record<string, number>>;
  suppressions: Readonly<Record<string, number>>;
}

export interface GateOptions {
  maxNewSuppressions: number;
  requireOwnerUnder: readonly string[];   // path prefixes
}

export interface GateResult {
  exitCode: number;
  lines: string[];
}

export function runGate(
  baselines: Baselines,
  current: readonly FileReport[],
  options: GateOptions,
): GateResult;
```

Errors, each on its own line:

- `E any-ratchet <path>: <was> -> <now>` when `anyCount` exceeds
  `baselines.any[path]`, treating a missing baseline entry as `0`
- `E owner-missing <path>` when `owner` is `null` and the path starts with any
  of the `requireOwnerUnder` prefixes
- `E suppression-budget: <n> new, limit <max>` — emitted at most once, when the
  total of `max(0, now - baseline)` across every file exceeds
  `maxNewSuppressions`. A file that removed suppressions does not fund another
  file adding them; that is what the `max(0, ...)` is for.

Information lines: `I any-ratchet <path>: <was> -> <now>` when the count went
down against a baseline entry that exists.

Output order: every `E` line sorted ascending, then every `I` line sorted
ascending, then exactly one summary line:

```
SUMMARY files=<count> any=<total anyCount> suppressions=<total suppressions>
```

`exitCode` is `1` when there is at least one `E` line and `0` otherwise.

Worked example — baselines `{ any: { "src/a.ts": 2 }, suppressions: {} }`,
options `{ maxNewSuppressions: 1, requireOwnerUnder: ["src/billing/"] }`, and
current

```ts
[
  { path: "src/a.ts", anyCount: 1, suppressions: 0, owner: "ada" },
  { path: "src/billing/tax.ts", anyCount: 1, suppressions: 2, owner: null },
]
```

produces, in order: `E any-ratchet src/billing/tax.ts: 0 -> 1`,
`E owner-missing src/billing/tax.ts`, `E suppression-budget: 2 new, limit 1`,
`I any-ratchet src/a.ts: 2 -> 1`, `SUMMARY files=2 any=2 suppressions=2`, with
an exit code of `1`.

Honest difficulty note: no single rule here is hard. The work is in the
ordering and in the fact that the sort is over rendered strings, so
`E any-ratchet` sorts before `E owner-missing` before `E suppression-budget`
without you doing anything — check that this is true for your rule names before
you rely on it.

```
uv run dojo test typescript v3tc01_incremental_migration challenge
```

references.solution.ts:
// v3tc01_incremental_migration / challenge - reference solution (author only).

export interface FileReport {
  path: string;
  anyCount: number;
  suppressions: number;
  owner: string | null;
}

export interface Baselines {
  any: Readonly<Record<string, number>>;
  suppressions: Readonly<Record<string, number>>;
}

export interface GateOptions {
  maxNewSuppressions: number;
  requireOwnerUnder: readonly string[];
}

export interface GateResult {
  exitCode: number;
  lines: string[];
}

export function runGate(
  baselines: Baselines,
  current: readonly FileReport[],
  options: GateOptions,
): GateResult {
  const errors: string[] = [];
  const infos: string[] = [];
  let newSuppressions = 0;
  let totalAny = 0;
  let totalSuppressions = 0;

  for (const file of current) {
    totalAny += file.anyCount;
    totalSuppressions += file.suppressions;

    const wasAny = baselines.any[file.path] ?? 0;
    if (file.anyCount > wasAny) {
      errors.push(`E any-ratchet ${file.path}: ${wasAny} -> ${file.anyCount}`);
    } else if (
      baselines.any[file.path] !== undefined &&
      file.anyCount < wasAny
    ) {
      infos.push(`I any-ratchet ${file.path}: ${wasAny} -> ${file.anyCount}`);
    }

    if (
      file.owner === null &&
      options.requireOwnerUnder.some((prefix) => file.path.startsWith(prefix))
    ) {
      errors.push(`E owner-missing ${file.path}`);
    }

    const wasSuppressions = baselines.suppressions[file.path] ?? 0;
    newSuppressions += Math.max(0, file.suppressions - wasSuppressions);
  }

  if (newSuppressions > options.maxNewSuppressions) {
    errors.push(
      `E suppression-budget: ${newSuppressions} new, limit ${options.maxNewSuppressions}`,
    );
  }

  errors.sort();
  infos.sort();
  const summary = `SUMMARY files=${current.length} any=${totalAny} suppressions=${totalSuppressions}`;
  return {
    exitCode: errors.length > 0 ? 1 : 0,
    lines: [...errors, ...infos, summary],
  };
}

// v3tc01_incremental_migration / review1 - reference solution (author only).

export const STRICT_FAMILY = [
  "alwaysStrict",
  "noImplicitAny",
  "noImplicitThis",
  "strictBindCallApply",
  "strictFunctionTypes",
  "strictNullChecks",
  "strictPropertyInitialization",
  "useUnknownInCatchVariables",
] as const;

export type StrictFlag = (typeof STRICT_FAMILY)[number];

export interface RawConfig {
  extends?: string;
  compilerOptions?: Readonly<Record<string, unknown>>;
}

function asBoolean(value: unknown): boolean | undefined {
  return typeof value === "boolean" ? value : undefined;
}

export function effectiveStrictFlags(
  configs: Readonly<Record<string, RawConfig>>,
  entry: string,
): Record<StrictFlag, boolean> {
  const chain: string[] = [];
  const seen = new Set<string>();
  let name: string | undefined = entry;

  while (name !== undefined) {
    const config: RawConfig | undefined = configs[name];
    if (config === undefined) throw new Error(`unknown config: ${name}`);
    if (seen.has(name)) {
      throw new Error(`circular extends: ${[...chain, name].join(" -> ")}`);
    }
    seen.add(name);
    chain.push(name);
    name = config.extends;
  }

  // Root first, so nearer configs overwrite what they inherit.
  const merged: Record<string, unknown> = {};
  for (const step of [...chain].reverse()) {
    Object.assign(merged, configs[step]?.compilerOptions ?? {});
  }

  const strict = asBoolean(merged["strict"]) ?? false;
  const result = {} as Record<StrictFlag, boolean>;
  for (const flag of STRICT_FAMILY) {
    result[flag] = asBoolean(merged[flag]) ?? strict;
  }
  return result;
}

// v3tc02_async_cancellation / ex1 - reference solution (author only).

export function throwIfAborted(signal: AbortSignal): void {
  if (signal.aborted) throw signal.reason;
}

export function abortable<T>(
  promise: Promise<T>,
  signal: AbortSignal,
): Promise<T> {
  if (signal.aborted) {
    // Never subscribe to a signal that has already fired.
    return Promise.reject(signal.reason);
  }
  return new Promise<T>((resolve, reject) => {
    const onAbort = () => {
      cleanup();
      reject(signal.reason);
    };
    const cleanup = () => signal.removeEventListener("abort", onAbort);
    signal.addEventListener("abort", onAbort);
    promise.then(
      (value) => {
        cleanup();
        resolve(value);
      },
      (reason: unknown) => {
        cleanup();
        reject(reason);
      },
    );
  });
}

