export type DeferredState = "pending" | "fulfilled" | "rejected";

export interface Deferred<T> {
  readonly promise: Promise<T>;
  resolve: (
    ...args: [T] extends [void]
      ? [value?: T | PromiseLike<T>]
      : [value: T | PromiseLike<T>]
  ) => void;
  reject: (reason?: unknown) => void;
  readonly state: DeferredState;
}

export function deferred<T>(): Deferred<T> {
  let resolveRaw!: (value: T | PromiseLike<T>) => void;
  let rejectRaw!: (reason?: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolveRaw = res;
    rejectRaw = rej;
  });

  let current: DeferredState = "pending";
  // Derived from the promise, so a pending thenable keeps us pending.
  promise.then(
    () => {
      current = "fulfilled";
    },
    () => {
      current = "rejected";
    },
  );

  return {
    promise,
    // The conditional tuple always carries at most one value of the right type.
    resolve: ((value?: T | PromiseLike<T>) =>
      resolveRaw(value as T)) as Deferred<T>["resolve"],
    reject: rejectRaw,
    get state() {
      return current;
    },
  };
}

