// v3tc02_async_cancellation / ex5 - reference solution (author only).

export function mapWithLimit<T, R>(
  items: readonly T[],
  limit: number,
  fn: (item: T, index: number, signal: AbortSignal) => Promise<R>,
  signal: AbortSignal,
): Promise<R[]> {
  if (!Number.isFinite(limit) || limit < 1) {
    throw new RangeError("limit must be at least 1");
  }
  if (signal.aborted) return Promise.reject(signal.reason);
  if (items.length === 0) return Promise.resolve([]);

  const results = new Array<R>(items.length);
  let next = 0;

  const worker = async (): Promise<void> => {
    while (next < items.length) {
      if (signal.aborted) throw signal.reason;
      const index = next;
      next += 1;
      results[index] = await fn(items[index] as T, index, signal);
    }
  };

  const size = Math.min(Math.floor(limit), items.length);
  return Promise.all(Array.from({ length: size }, worker)).then(() => results);
}

exercises.hints:
## Hint 1

Count the outstanding entries. Each input decides itself once, an abort decides
all the remaining ones at once, and when the count reaches zero you resolve.
That is the whole algorithm; everything else is bookkeeping.

## Hint 2

Fill a slots array with `undefined`, and let a small helper enforce
decide-once:

```ts
const slots = new Array<Settled<T> | undefined>(promises.length);
let outstanding = promises.length;
const decide = (index: number, outcome: Settled<T>) => {
  if (slots[index] !== undefined) return;
  slots[index] = outcome;
  outstanding -= 1;
  if (outstanding === 0) finish();
};
```

The `if` at the top is what makes "settled before the abort keeps its outcome"
true without any timestamp comparison.

## Hint 3

Attach handlers to every input before you attach the abort listener, so that
an input which is already resolved gets its microtask queued first. It will not
run before the current synchronous block ends either way — but the ordering
question is worth thinking through, because it is exactly the sort of thing
that makes a test flake.

Left to you: whether `slots` is typed with `| undefined` and asserted at the
end, or whether you track decisions in a parallel `boolean[]`. Both work; one
of them cannot lie to you.

