// v3tc02_async_cancellation / ex6 - reference solution (author only).

export type Settled<T> =
  | { status: "fulfilled"; value: T }
  | { status: "rejected"; reason: unknown }
  | { status: "aborted" };

export function settleAll<T>(
  promises: readonly Promise<T>[],
  signal: AbortSignal,
): Promise<Settled<T>[]> {
  if (promises.length === 0) return Promise.resolve([]);

  return new Promise<Settled<T>[]>((resolve) => {
    const slots = new Array<Settled<T> | undefined>(promises.length);
    let outstanding = promises.length;
    let onAbort: (() => void) | undefined;

    const finish = () => {
      if (onAbort) signal.removeEventListener("abort", onAbort);
      resolve(slots as Settled<T>[]);
    };

    const decide = (index: number, outcome: Settled<T>): void => {
      if (slots[index] !== undefined) return;
      slots[index] = outcome;
      outstanding -= 1;
      if (outstanding === 0) finish();
    };

    promises.forEach((promise, index) => {
      promise.then(
        (value) => decide(index, { status: "fulfilled", value }),
        (reason: unknown) => decide(index, { status: "rejected", reason }),
      );
    });

    const abortAll = () => {
      for (let index = 0; index < slots.length; index += 1) {
        decide(index, { status: "aborted" });
      }
    };

    if (signal.aborted) {
      abortAll();
      return;
    }
    onAbort = abortAll;
    signal.addEventListener("abort", onAbort, { once: true });
  });
}

// v3tc02_async_cancellation / ex7 - reference solution (author only).

export interface Emitter<M> {
  addEventListener<K extends keyof M>(
    type: K,
    listener: (payload: M[K]) => void,
  ): void;
  removeEventListener<K extends keyof M>(
    type: K,
    listener: (payload: M[K]) => void,
  ): void;
}

export function once<M, K extends keyof M>(
  emitter: Emitter<M>,
  type: K,
  options?: { signal?: AbortSignal },
): Promise<M[K]> {
  const signal = options?.signal;
  if (signal?.aborted) return Promise.reject(signal.reason);

  return new Promise<M[K]>((resolve, reject) => {
    const listener = (payload: M[K]) => {
      cleanup();
      resolve(payload);
    };
    const onAbort = () => {
      cleanup();
      reject(signal?.reason);
    };
    const cleanup = () => {
      emitter.removeEventListener(type, listener);
      signal?.removeEventListener("abort", onAbort);
    };

    emitter.addEventListener(type, listener);
    signal?.addEventListener("abort", onAbort);
  });
}

