// v3tc02_async_cancellation / ex8 - reference solution (author only).

export interface RetryOptions {
  attempts: number;
  delay: (attempt: number) => Promise<void>;
  signal: AbortSignal;
}

function raceAbort<T>(promise: Promise<T>, signal: AbortSignal): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const onAbort = () => {
      cleanup();
      reject(signal.reason);
    };
    const cleanup = () => signal.removeEventListener("abort", onAbort);
    signal.addEventListener("abort", onAbort);
    promise.then(
      (value) => {
        cleanup();
        resolve(value);
      },
      (reason: unknown) => {
        cleanup();
        reject(reason);
      },
    );
  });
}

export async function retry<T>(
  task: (signal: AbortSignal) => Promise<T>,
  options: RetryOptions,
): Promise<T> {
  if (!Number.isFinite(options.attempts) || options.attempts < 1) {
    throw new RangeError("attempts must be at least 1");
  }
  const { signal } = options;

  for (let attempt = 1; ; attempt += 1) {
    if (signal.aborted) throw signal.reason;
    try {
      return await task(signal);
    } catch (reason) {
      // A cancellation is not a failure to retry.
      if (signal.aborted) throw signal.reason;
      if (attempt >= options.attempts) throw reason;
      await raceAbort(options.delay(attempt), signal);
    }
  }
}

exercises.hints:
## Hint 1

One `Map` from key string to an entry, and the entry holds three things: the
shared promise, the controller that can abort the shared work, and the count of
live callers. Everything in the prompt is an operation on that entry.

## Hint 2

Each caller gets its own promise built on top of the shared one — this is `ex1`
with a bit more bookkeeping in the cleanup:

```ts
return new Promise<V>((resolve, reject) => {
  const onAbort = () => { detach(); reject(signal.reason) };
  const detach = () => {
    signal.removeEventListener("abort", onAbort);
    entry.waiters -= 1;
    if (entry.waiters === 0) { /* last one out */ }
  };
  signal.addEventListener("abort", onAbort);
  entry.promise.then((v) => { detach(); resolve(v) }, (e) => { detach(); reject(e) });
});
```

Careful: `detach` runs on all three paths, so `waiters` must not be decremented
twice for one caller. A boolean guard inside `detach` is the simplest fix.

## Hint 3

For the unhandled-rejection rule, attach a no-op rejection handler to the
shared promise at the moment you create it:

```ts
shared.catch(() => {})   // owned by the entry, not by any caller
```

That does not swallow anything the callers see — each of them attached their
own handlers — it just tells the runtime the shared promise is not orphaned.

Left to you: whether removing the map entry happens in the shared promise's
`finally`, in each caller's `detach`, or both. There is a correct answer and it
involves making sure a late settlement does not delete an entry that a newer
`load` has already created under the same key.

