// v3tc02_async_cancellation / challenge - reference solution (author only).

export interface Loader<K, V> {
  load(key: K, signal: AbortSignal): Promise<V>;
  readonly inFlight: number;
}

interface Entry<V> {
  promise: Promise<V>;
  controller: AbortController;
  waiters: number;
}

export function createLoader<K, V>(
  fetcher: (key: K, signal: AbortSignal) => Promise<V>,
  keyOf: (key: K) => string,
): Loader<K, V> {
  const entries = new Map<string, Entry<V>>();

  const drop = (id: string, entry: Entry<V>): void => {
    // Only remove our own entry: a newer load may already own this key.
    if (entries.get(id) === entry) entries.delete(id);
  };

  return {
    load(key: K, signal: AbortSignal): Promise<V> {
      if (signal.aborted) return Promise.reject(signal.reason);
      const id = keyOf(key);

      let entry = entries.get(id);
      if (entry === undefined) {
        const controller = new AbortController();
        const created: Entry<V> = {
          controller,
          waiters: 0,
          promise: Promise.resolve().then(() => fetcher(key, controller.signal)),
        };
        // The entry owns the shared rejection; callers attach their own.
        created.promise.then(
          () => drop(id, created),
          () => drop(id, created),
        );
        entries.set(id, created);
        entry = created;
      }

      const joined = entry;
      joined.waiters += 1;

      return new Promise<V>((resolve, reject) => {
        let detached = false;
        const detach = () => {
          if (detached) return;
          detached = true;
          signal.removeEventListener("abort", onAbort);
          joined.waiters -= 1;
        };
        const onAbort = () => {
          detach();
          if (joined.waiters === 0) {
            joined.controller.abort(signal.reason);
            drop(id, joined);
          }
          reject(signal.reason);
        };

        signal.addEventListener("abort", onAbort);
        joined.promise.then(
          (value) => {
            detach();
            resolve(value);
          },
          (reason: unknown) => {
            detach();
            reject(reason);
          },
        );
      });
    },
    get inFlight() {
      return entries.size;
    },
  };
}

// v3tc02_async_cancellation / review1 - reference solution (author only).

export type Timed<T> =
  | { status: "ok"; value: T }
  | { status: "timeout" }
  | { status: "failed"; reason: unknown };

export async function withTimeout<T>(
  task: (signal: AbortSignal) => Promise<T>,
  ms: number,
  timer: (ms: number, signal: AbortSignal) => Promise<void>,
): Promise<Timed<T>> {
  const taskControl = new AbortController();
  const timerControl = new AbortController();

  const first = await Promise.race([
    task(taskControl.signal).then(
      (value) => ({ kind: "ok", value }) as const,
      (reason: unknown) => ({ kind: "failed", reason }) as const,
    ),
    timer(ms, timerControl.signal).then(() => ({ kind: "timeout" }) as const),
  ]);

  if (first.kind === "timeout") {
    taskControl.abort("timeout");
    return { status: "timeout" };
  }
  timerControl.abort("settled");
  return first.kind === "ok"
    ? { status: "ok", value: first.value }
    : { status: "failed", reason: first.reason };
}

