// v3tc03_testing_types / ex5 - reference solution (author only).

export type AnyFn = (...args: never[]) => unknown;

export type MethodKeys<T> = {
  [K in keyof T]-?: NonNullable<T[K]> extends AnyFn ? K : never;
}[keyof T];

export interface MockFn<F extends AnyFn> {
  (...args: Parameters<F>): ReturnType<F>;
  readonly calls: Parameters<F>[];
  returns(value: ReturnType<F>): MockFn<F>;
  throws(reason: unknown): MockFn<F>;
}

type Behaviour<F extends AnyFn> =
  | { kind: "none" }
  | { kind: "value"; value: ReturnType<F> }
  | { kind: "throw"; reason: unknown };

export function mockFn<F extends AnyFn>(impl?: F): MockFn<F> {
  const calls: Parameters<F>[] = [];
  let behaviour: Behaviour<F> = { kind: "none" };

  const mock = (...args: Parameters<F>): ReturnType<F> => {
    calls.push(args);
    if (behaviour.kind === "throw") throw behaviour.reason;
    if (behaviour.kind === "value") return behaviour.value;
    if (impl) return impl(...(args as never[])) as ReturnType<F>;
    return undefined as ReturnType<F>;
  };

  const api = mock as unknown as {
    calls: Parameters<F>[];
    returns: MockFn<F>["returns"];
    throws: MockFn<F>["throws"];
  };
  api.calls = calls;
  api.returns = (value) => {
    behaviour = { kind: "value", value };
    return mock as MockFn<F>;
  };
  api.throws = (reason) => {
    behaviour = { kind: "throw", reason };
    return mock as MockFn<F>;
  };
  return mock as MockFn<F>;
}

export function mockOf<T extends object>(name: string, stubs: Partial<T>): T {
  return new Proxy({} as T, {
    get(_target, key) {
      // Awaiting anything probes for `then`; never throw for that.
      if (key === "then") return undefined;
      if (key in stubs) return (stubs as Record<PropertyKey, unknown>)[key];
      throw new Error(`${name}.${String(key)} is not stubbed`);
    },
  });
}

