```

references.solution.ts:
// v3tc03_testing_types / ex6 - reference solution (author only).

export type AnyFn = (...args: never[]) => unknown;

export type MethodKeys<T> = {
  [K in keyof T]-?: NonNullable<T[K]> extends AnyFn ? K : never;
}[keyof T];

export interface Spy<T, K extends MethodKeys<T>> {
  readonly calls: T[K] extends (...args: infer A) => unknown ? A[] : never;
  restore(): void;
}

export function spyOn<T extends object, K extends MethodKeys<T>>(
  target: T,
  key: K,
): Spy<T, K> {
  const original = (target as Record<PropertyKey, unknown>)[key as PropertyKey];
  if (typeof original !== "function") {
    throw new TypeError(`${String(key)} is not a method`);
  }

  const own = Object.getOwnPropertyDescriptor(target, key as PropertyKey);
  const calls: unknown[][] = [];
  const fn = original as (...args: unknown[]) => unknown;

  const spy = function (this: unknown, ...args: unknown[]): unknown {
    calls.push(args);
    return fn.apply(this, args);
  };

  (target as Record<PropertyKey, unknown>)[key as PropertyKey] = spy;

  let restored = false;
  return {
    calls: calls as Spy<T, K>["calls"],
    restore(): void {
      if (restored) return;
      restored = true;
      if (own === undefined) {
        // It lived on the prototype; leaving an own property would be a leak.
        delete (target as Record<PropertyKey, unknown>)[key as PropertyKey];
      } else {
        Object.defineProperty(target, key as PropertyKey, own);
      }
    },
  };
}

