```

references.solution.ts:
// v3tc03_testing_types / ex7 - reference solution (author only).

export interface Repository<T, K extends keyof T> {
  get(id: T[K]): Promise<T | undefined>;
  put(item: T): Promise<void>;
  remove(id: T[K]): Promise<boolean>;
  query(predicate: (item: T) => boolean): Promise<T[]>;
}

export interface FakeRepository<T, K extends keyof T> extends Repository<T, K> {
  readonly size: number;
  failNext(reason: unknown): void;
}

const NOTHING = Symbol("nothing");

function copy<V>(value: V): V {
  if (Array.isArray(value)) return value.map(copy) as unknown as V;
  if (typeof value === "object" && value !== null) {
    const proto: unknown = Object.getPrototypeOf(value);
    if (proto !== Object.prototype && proto !== null) return value;
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value)) out[k] = copy(v);
    return out as V;
  }
  return value;
}

export function createFakeRepository<T extends object, K extends keyof T>(
  key: K,
  seed?: readonly T[],
): FakeRepository<T, K> {
  const store = new Map<T[K], T>();
  for (const item of seed ?? []) store.set(item[key], copy(item));
  let pending: unknown = NOTHING;

  const check = (): void => {
    if (pending !== NOTHING) {
      const reason = pending;
      pending = NOTHING;
      throw reason;
    }
  };

  return {
    async get(id: T[K]): Promise<T | undefined> {
      check();
      const found = store.get(id);
      return found === undefined ? undefined : copy(found);
    },
    async put(item: T): Promise<void> {
      check();
      store.set(item[key], copy(item));
    },
    async remove(id: T[K]): Promise<boolean> {
      check();
      return store.delete(id);
    },
    async query(predicate: (item: T) => boolean): Promise<T[]> {
      check();
      const found: T[] = [];
      for (const item of store.values()) {
        if (predicate(item)) found.push(copy(item));
      }
      return found;
    },
    failNext(reason: unknown): void {
      pending = reason;
    },
    get size(): number {
      return store.size;
    },
  };
}

