```

references.solution.ts:
// v3tc03_testing_types / review1 - reference solution (author only).

export type Kind = "credit" | "debit" | "refund";

export interface Entry {
  kind: Kind;
  amount: number;
}

export interface Case<K extends Kind> {
  input: { kind: K; amount: number };
  expected: string;
}

export type CaseTable = { [K in Kind]: Case<K> };

function assertNever(value: never): never {
  throw new Error(`unhandled kind: ${JSON.stringify(value)}`);
}

export function describeEntry(entry: Entry): string {
  switch (entry.kind) {
    case "credit":
      return `+${entry.amount.toFixed(2)}`;
    case "debit":
      return `-${entry.amount.toFixed(2)}`;
    case "refund":
      return `refund of ${entry.amount.toFixed(2)}`;
    default:
      return assertNever(entry.kind);
  }
}

export const CASES: CaseTable = {
  credit: { input: { kind: "credit", amount: 12 }, expected: "+12.00" },
  debit: { input: { kind: "debit", amount: 3.5 }, expected: "-3.50" },
  refund: { input: { kind: "refund", amount: 8 }, expected: "refund of 8.00" },
};

export function runTable(table: CaseTable): string[] {
  const failures: string[] = [];
  for (const [kind, testCase] of Object.entries(table)) {
    const actual = describeEntry(testCase.input);
    if (actual !== testCase.expected) {
      failures.push(`${kind}: expected ${testCase.expected}, got ${actual}`);
    }
  }
  return failures;
}

// v3tc04_esm_cjs_resolution / ex1 - reference solution (author only).

export type ExportsField = string | null | { [key: string]: ExportsField };

function isConditions(
  value: ExportsField,
): value is { [key: string]: ExportsField } {
  return typeof value === "object" && value !== null;
}

/** Resolve a target that may be a string, a block, or nested conditions. */
function resolveTarget(
  value: ExportsField,
  conditions: readonly string[],
): string | null {
  if (value === null) return null;
  if (typeof value === "string") return value;
  for (const [key, nested] of Object.entries(value)) {
    if (key === "default" || conditions.includes(key)) {
      const resolved = resolveTarget(nested, conditions);
      if (resolved !== null) return resolved;
      return null;
    }
  }
  return null;
}

export function resolveExports(
  exports: ExportsField,
  subpath: string,
  conditions: readonly string[],
): string | null {
  if (exports === null) return null;
  if (typeof exports === "string") {
    return subpath === "." ? exports : null;
  }

  const keys = Object.keys(exports);
  const isSubpathMap = keys.length > 0 && keys[0]!.startsWith(".");
  if (!isSubpathMap) {
    return subpath === "." ? resolveTarget(exports, conditions) : null;
  }

  const exact = exports[subpath];
  if (exact !== undefined) return resolveTarget(exact, conditions);

  let bestPrefix = -1;
  let best: { target: ExportsField; captured: string } | null = null;
  for (const key of keys) {
    const star = key.indexOf("*");
    if (star === -1) continue;
    const prefix = key.slice(0, star);
    const suffix = key.slice(star + 1);
    if (
      subpath.length >= prefix.length + suffix.length &&
      subpath.startsWith(prefix) &&
      subpath.endsWith(suffix) &&
      prefix.length > bestPrefix
    ) {
      bestPrefix = prefix.length;
      best = {
        target: exports[key] as ExportsField,
        captured: subpath.slice(prefix.length, subpath.length - suffix.length),
      };
    }
  }
  if (best === null) return null;

  const target = resolveTarget(best.target, conditions);
  return target === null ? null : target.replace("*", best.captured);
}

// v3tc04_esm_cjs_resolution / ex2 - reference solution (author only).

export type Mode = "node10" | "node16-cjs" | "node16-esm";

const CJS_EXTENSIONS = [".ts", ".tsx", ".d.ts", ".js", ".jsx"] as const;

const ESM_REWRITES: Record<string, readonly string[]> = {
  ".js": [".ts", ".tsx", ".d.ts"],
  ".mjs": [".mts", ".d.mts"],
  ".cjs": [".cts", ".d.cts"],
};

function candidates(specifier: string, mode: Mode): string[] {
  const list = [specifier];
  if (mode === "node16-esm") {
    for (const [output, sources] of Object.entries(ESM_REWRITES)) {
      if (!specifier.endsWith(output)) continue;
      const base = specifier.slice(0, -output.length);
      for (const source of sources) list.push(base + source);
    }
    return list;
  }
  for (const extension of CJS_EXTENSIONS) list.push(specifier + extension);
  for (const extension of CJS_EXTENSIONS) {
    list.push(`${specifier}/index${extension}`);
  }
  return list;
}

export function resolveRelative(
  specifier: string,
  files: readonly string[],
  mode: Mode,
): string | null {
  const existing = new Set(files);
  for (const candidate of candidates(specifier, mode)) {
    if (existing.has(candidate)) return candidate;
  }
  return null;
}

// v3tc04_esm_cjs_resolution / ex3 - reference solution (author only).

export type Format = "esm" | "cjs";

const ALWAYS: Record<string, Format> = {
  ".mjs": "esm",
  ".mts": "esm",
  ".cjs": "cjs",
  ".cts": "cjs",
  ".json": "cjs",
};

const FROM_PACKAGE_TYPE = new Set([".js", ".jsx", ".ts", ".tsx"]);

function lastExtension(path: string): string {
  const dot = path.lastIndexOf(".");
  return dot === -1 ? "" : path.slice(dot);
}

export function formatOf(
  path: string,
  nearestPackageType: "module" | "commonjs" | undefined,
): Format {
  const extension = lastExtension(path);
  const fixed = ALWAYS[extension];
  if (fixed !== undefined) return fixed;
  if (FROM_PACKAGE_TYPE.has(extension)) {
    // No "type" field means CommonJS - the pre-2019 compatibility rule.
    return nearestPackageType === "module" ? "esm" : "cjs";
  }
  throw new Error(`unknown extension: ${extension}`);
}

const DECLARATION: Record<string, string> = {
  ".ts": ".d.ts",
  ".tsx": ".d.ts",
  ".mts": ".d.mts",
  ".cts": ".d.cts",
};

export function declarationFor(path: string): string {
  if (path.endsWith(".d.ts") || path.endsWith(".d.mts") || path.endsWith(".d.cts")) {
    throw new Error(`no declaration output for ${path}`);
  }
  const extension = lastExtension(path);
  const output = DECLARATION[extension];
  if (output === undefined) {
    throw new Error(`no declaration output for ${path}`);
  }
  return path.slice(0, -extension.length) + output;
}

// v3tc04_esm_cjs_resolution / ex4 - reference solution (author only).

const SPECIFIER = /(\bfrom\s*|\bimport\s*)(["'])((?:\.\.?\/)[^"']*)\2/g;

const SKIP = [".js", ".mjs", ".cjs", ".json", ".node"];

const OUTPUT: Record<".ts" | ".mts" | ".cts", string> = {
  ".ts": ".js",
  ".mts": ".mjs",
  ".cts": ".cjs",
};

export function addExtensions(
  source: string,
  from: ".ts" | ".mts" | ".cts",
): string {
  const extension = OUTPUT[from];
  return source.replace(
    SPECIFIER,
    (match: string, lead: string, quote: string, specifier: string) => {
      if (SKIP.some((known) => specifier.endsWith(known))) return match;
      return `${lead}${quote}${specifier}${extension}${quote}`;
    },
  );
}

// v3tc04_esm_cjs_resolution / ex5 - reference solution (author only).

function isIndexable(value: unknown): value is Record<string, unknown> {
  return (
    (typeof value === "object" && value !== null) || typeof value === "function"
  );
}

export function interopDefault(mod: unknown): unknown {
  if (isIndexable(mod) && mod["__esModule"] === true) {
    // Transpiled ESM: the real default lives inside.
    return mod["default"];
  }
  return mod;
}

export function namedExports(mod: unknown): string[] {
  if (!isIndexable(mod)) return [];
  return Object.keys(mod)
    .filter((key) => key !== "default" && key !== "__esModule")
    .sort();
}

export function interopNamespace(mod: unknown): Record<string, unknown> {
  const namespace: Record<string, unknown> = {};
  if (isIndexable(mod)) {
    for (const key of namedExports(mod)) namespace[key] = mod[key];
  }
  namespace["default"] = interopDefault(mod);
  // Real namespace objects are immutable; mimic that so bugs surface early.
  return Object.freeze(namespace);
}

