// v3tc04_esm_cjs_resolution / ex6 - reference solution (author only).

export interface Instance {
  package: string;
  format: "esm" | "cjs";
  importedBy: string;
}

export interface Hazard {
  package: string;
  importers: string[];
}

export function findDualPackages(instances: readonly Instance[]): Hazard[] {
  const groups = new Map<
    string,
    { formats: Set<string>; importers: Set<string> }
  >();

  for (const instance of instances) {
    let group = groups.get(instance.package);
    if (group === undefined) {
      group = { formats: new Set(), importers: new Set() };
      groups.set(instance.package, group);
    }
    group.formats.add(instance.format);
    group.importers.add(instance.importedBy);
  }

  const hazards: Hazard[] = [];
  for (const [name, group] of groups) {
    if (group.formats.size < 2) continue;
    hazards.push({ package: name, importers: [...group.importers].sort() });
  }
  return hazards.sort((a, b) =>
    a.package < b.package ? -1 : a.package > b.package ? 1 : 0,
  );
}

export function dangerousHazards(
  hazards: readonly Hazard[],
  stateful: readonly string[],
): string[] {
  const risky = new Set(stateful);
  return [...new Set(hazards.map((h) => h.package))]
    .filter((name) => risky.has(name))
    .sort();
}

// v3tc04_esm_cjs_resolution / ex7 - reference solution (author only).

export interface PackageJson {
  name: string;
  type?: "module" | "commonjs";
  main?: string;
  types?: string;
  exports?: unknown;
}

export function checkPackage(pkg: PackageJson): string[] {
  const found = new Set<string>();
  const targets = new Set<string>();

  const walk = (node: unknown, path: string, conditions: string[]): void => {
    if (typeof node === "string") {
      targets.add(node);
      if (conditions.includes("require") && node.endsWith(".mjs")) {
        found.add(`exports: require condition resolves to ESM ${node}`);
      }
      if (conditions.includes("import") && node.endsWith(".cjs")) {
        found.add(`exports: import condition resolves to CJS ${node}`);
      }
      return;
    }
    if (typeof node !== "object" || node === null || Array.isArray(node)) return;

    const keys = Object.keys(node as Record<string, unknown>);
    if (keys.length === 0) return;
    const isSubpathMap = keys[0]!.startsWith(".");

    if (isSubpathMap) {
      if (!keys.includes(".")) found.add(`exports: "." is not exported`);
    } else {
      if (keys.includes("types") && keys[0] !== "types") {
        found.add(`exports: "types" must be the first key in ${path}`);
      }
      if (!keys.includes("default")) {
        found.add(`exports: no default condition in ${path}`);
      }
    }

    for (const key of keys) {
      const value = (node as Record<string, unknown>)[key];
      const nextPath = path === "." ? key : `${path}/${key}`;
      walk(
        value,
        isSubpathMap ? key : nextPath,
        isSubpathMap ? conditions : [...conditions, key],
      );
    }
  };

  if (pkg.exports !== undefined) {
    walk(pkg.exports, ".", []);
    if (pkg.main !== undefined && !targets.has(pkg.main)) {
      found.add(`main "${pkg.main}" is not reachable through exports`);
    }
  }

  return [...found].sort();
}

// v3tc04_esm_cjs_resolution / ex8 - reference solution (author only).

export type ExportsField = string | null | { [key: string]: ExportsField };

export interface TypesPackage {
  exports?: ExportsField;
  typesVersions?: Record<string, Record<string, string[]>>;
  types?: string;
  typings?: string;
}

function resolveTarget(
  value: ExportsField,
  conditions: readonly string[],
): string | null {
  if (value === null) return null;
  if (typeof value === "string") return value;
  for (const [key, nested] of Object.entries(value)) {
    if (key === "default" || conditions.includes(key)) {
      return resolveTarget(nested, conditions);
    }
  }
  return null;
}

function resolveExports(
  exports: ExportsField,
  subpath: string,
  conditions: readonly string[],
): string | null {
  if (exports === null) return null;
  if (typeof exports === "string") return subpath === "." ? exports : null;
  const keys = Object.keys(exports);
  if (keys.length === 0) return null;
  if (!keys[0]!.startsWith(".")) {
    return subpath === "." ? resolveTarget(exports, conditions) : null;
  }
  const exact = exports[subpath];
  if (exact !== undefined) return resolveTarget(exact, conditions);

  let bestPrefix = -1;
  let best: { target: ExportsField; captured: string } | null = null;
  for (const key of keys) {
    const star = key.indexOf("*");
    if (star === -1) continue;
    const prefix = key.slice(0, star);
    const suffix = key.slice(star + 1);
    if (
      subpath.startsWith(prefix) &&
      subpath.endsWith(suffix) &&
      subpath.length >= prefix.length + suffix.length &&
      prefix.length > bestPrefix
    ) {
      bestPrefix = prefix.length;
      best = {
        target: exports[key] as ExportsField,
        captured: subpath.slice(prefix.length, subpath.length - suffix.length),
      };
    }
  }
  if (best === null) return null;
  const target = resolveTarget(best.target, conditions);
  return target === null ? null : target.replace("*", best.captured);
}

type Version = readonly [number, number];

function parseVersion(text: string): Version {
  const [major = "0", minor = "0"] = text.split(".");
  return [Number(major), Number(minor)];
}

function compare(a: Version, b: Version): number {
  return a[0] - b[0] || a[1] - b[1];
}

function rangeMatches(range: string, version: Version): boolean {
  if (range === "*") return true;
  if (range.startsWith(">=")) {
    return compare(version, parseVersion(range.slice(2))) >= 0;
  }
  if (range.startsWith("<")) {
    return compare(version, parseVersion(range.slice(1))) < 0;
  }
  return false;
}

export function resolveTypes(
  pkg: TypesPackage,
  subpath: string,
  conditions: readonly string[],
  tsVersion: string,
): string | null {
  if (pkg.exports !== undefined) {
    return resolveExports(pkg.exports, subpath, ["types", ...conditions]);
  }

  if (pkg.typesVersions !== undefined) {
    const version = parseVersion(tsVersion);
    const key = subpath === "." ? "index" : subpath.replace(/^\.\//, "");
    for (const [range, mappings] of Object.entries(pkg.typesVersions)) {
      if (!rangeMatches(range, version)) continue;
      const exact = mappings[key];
      if (exact?.[0] !== undefined) return `./${exact[0]}`;
      for (const [pattern, targets] of Object.entries(mappings)) {
        const star = pattern.indexOf("*");
        if (star === -1 || targets[0] === undefined) continue;
        const prefix = pattern.slice(0, star);
        const suffix = pattern.slice(star + 1);
        if (!key.startsWith(prefix) || !key.endsWith(suffix)) continue;
        const captured = key.slice(prefix.length, key.length - suffix.length);
        return `./${targets[0].replace("*", captured)}`;
      }
      return null;
    }
    return null;
  }

  if (subpath !== ".") return null;
  return pkg.types ?? pkg.typings ?? null;
}

