// v3tc04_esm_cjs_resolution / challenge - reference solution (author only).

export type ExportsField = string | null | { [key: string]: ExportsField };

export interface Manifest {
  name: string;
  type?: "module" | "commonjs";
  exports?: ExportsField;
  imports?: Record<string, ExportsField>;
}

export type Format = "esm" | "cjs";

export interface Resolution {
  from: string;
  specifier: string;
  package: string;
  target: string;
  format: Format;
}

export interface Analysis {
  resolutions: Resolution[];
  hazards: string[];
  errors: string[];
}

function resolveTarget(
  value: ExportsField,
  conditions: readonly string[],
): string | null {
  if (value === null) return null;
  if (typeof value === "string") return value;
  for (const [key, nested] of Object.entries(value)) {
    if (key === "default" || conditions.includes(key)) {
      return resolveTarget(nested, conditions);
    }
  }
  return null;
}

function resolveExports(
  exports: ExportsField,
  subpath: string,
  conditions: readonly string[],
): string | null {
  if (exports === null) return null;
  if (typeof exports === "string") return subpath === "." ? exports : null;
  const keys = Object.keys(exports);
  if (keys.length === 0) return null;
  if (!keys[0]!.startsWith(".")) {
    return subpath === "." ? resolveTarget(exports, conditions) : null;
  }
  const exact = exports[subpath];
  if (exact !== undefined) return resolveTarget(exact, conditions);

  let bestPrefix = -1;
  let best: { target: ExportsField; captured: string } | null = null;
  for (const key of keys) {
    const star = key.indexOf("*");
    if (star === -1) continue;
    const prefix = key.slice(0, star);
    const suffix = key.slice(star + 1);
    if (
      subpath.startsWith(prefix) &&
      subpath.endsWith(suffix) &&
      subpath.length >= prefix.length + suffix.length &&
      prefix.length > bestPrefix
    ) {
      bestPrefix = prefix.length;
      best = {
        target: exports[key] as ExportsField,
        captured: subpath.slice(prefix.length, subpath.length - suffix.length),
      };
    }
  }
  if (best === null) return null;
  const target = resolveTarget(best.target, conditions);
  return target === null ? null : target.replace("*", best.captured);
}

const FIXED_FORMAT: Record<string, Format> = {
  ".mjs": "esm",
  ".cjs": "cjs",
  ".json": "cjs",
};

function formatOfTarget(target: string, manifest: Manifest): Format {
  const dot = target.lastIndexOf(".");
  const extension = dot === -1 ? "" : target.slice(dot);
  return (
    FIXED_FORMAT[extension] ?? (manifest.type === "module" ? "esm" : "cjs")
  );
}

function splitBare(specifier: string): { name: string; subpath: string } {
  const parts = specifier.split("/");
  const take = specifier.startsWith("@") ? 2 : 1;
  const rest = parts.slice(take).join("/");
  return {
    name: parts.slice(0, take).join("/"),
    subpath: rest === "" ? "." : `./${rest}`,
  };
}

export function analyse(
  packages: Readonly<Record<string, Manifest>>,
  edges: readonly { from: string; specifier: string }[],
): Analysis {
  const resolutions: Resolution[] = [];
  const errors: string[] = [];
  const formats = new Map<string, Set<Format>>();

  for (const edge of edges) {
    const importer = packages[edge.from];
    const fail = (code: string): void => {
      errors.push(`${edge.from} -> ${edge.specifier}: ${code}`);
    };
    if (importer === undefined) {
      fail("ERR_MODULE_NOT_FOUND");
      continue;
    }
    const conditions =
      importer.type === "module" ? ["import", "node"] : ["require", "node"];

    let owner: Manifest;
    let target: string | null;

    if (edge.specifier.startsWith("#")) {
      const entry = importer.imports?.[edge.specifier];
      if (entry === undefined) {
        fail("ERR_PACKAGE_IMPORT_NOT_DEFINED");
        continue;
      }
      owner = importer;
      target = resolveTarget(entry, conditions);
    } else if (edge.specifier.startsWith(".") || edge.specifier.startsWith("/")) {
      fail("ERR_UNSUPPORTED");
      continue;
    } else {
      const { name, subpath } = splitBare(edge.specifier);
      const found = packages[name];
      if (found === undefined) {
        fail("ERR_MODULE_NOT_FOUND");
        continue;
      }
      if (found.exports === undefined) {
        fail("ERR_PACKAGE_PATH_NOT_EXPORTED");
        continue;
      }
      owner = found;
      target = resolveExports(found.exports, subpath, conditions);
    }

    if (target === null) {
      fail("ERR_PACKAGE_PATH_NOT_EXPORTED");
      continue;
    }

    const format = formatOfTarget(target, owner);
    resolutions.push({
      from: edge.from,
      specifier: edge.specifier,
      package: owner.name,
      target,
      format,
    });
    const seen = formats.get(owner.name) ?? new Set<Format>();
    seen.add(format);
    formats.set(owner.name, seen);
  }

  const hazards = [...formats.entries()]
    .filter(([, seen]) => seen.size > 1)
    .map(([name]) => name)
    .sort();

  return { resolutions, hazards, errors };
}

// v3tc04_esm_cjs_resolution / review1 - reference solution (author only).

export type SpecifierKind =
  | "subpath-import"
  | "builtin"
  | "data-url"
  | "absolute"
  | "relative"
  | "bare";

const BUILTINS = new Set([
  "fs",
  "path",
  "http",
  "url",
  "events",
  "crypto",
  "util",
  "stream",
]);

const WINDOWS_DRIVE = /^[A-Za-z]:[\\/]/;

export function classifySpecifier(specifier: string): SpecifierKind {
  if (specifier.startsWith("#")) return "subpath-import";
  if (specifier.startsWith("node:") || BUILTINS.has(specifier)) return "builtin";
  if (specifier.startsWith("data:")) return "data-url";
  if (
    specifier.startsWith("/") ||
    specifier.startsWith("file:") ||
    WINDOWS_DRIVE.test(specifier)
  ) {
    return "absolute";
  }
  if (
    specifier.startsWith("./") ||
    specifier.startsWith("../") ||
    specifier === "." ||
    specifier === ".."
  ) {
    return "relative";
  }
  return "bare";
}

function isValidSegment(segment: string): boolean {
  return (
    segment.length > 0 &&
    segment === segment.toLowerCase() &&
    !segment.startsWith(".") &&
    !segment.startsWith("_")
  );
}

export function parseBare(
  specifier: string,
): { name: string; subpath: string } | null {
  if (classifySpecifier(specifier) !== "bare") return null;

  const parts = specifier.split("/");
  const take = specifier.startsWith("@") ? 2 : 1;
  if (parts.length < take) return null;

  const nameParts = parts.slice(0, take);
  const segments = take === 2 ? [nameParts[0]!.slice(1), nameParts[1]!] : nameParts;
  if (!segments.every((segment) => isValidSegment(segment ?? ""))) return null;

  const rest = parts.slice(take).join("/");
  return {
    name: nameParts.join("/"),
    subpath: rest === "" ? "." : `./${rest}`,
  };
}

