// v3tc05_project_references / ex3 - reference solution (author only).

export interface Project {
  path: string;
  references: readonly string[];
}

export interface BuildInfo {
  outputs: readonly string[];
  builtAt: number;
}

export interface Snapshot {
  fileTimes: Readonly<Record<string, number>>;
  buildInfos: Readonly<Record<string, BuildInfo>>;
}

export type Status =
  | "missing-buildinfo"
  | "missing-output"
  | "stale-input"
  | "stale-reference"
  | "up-to-date";

export function statusOf(
  project: Project,
  inputs: readonly string[],
  snapshot: Snapshot,
): Status {
  const info = snapshot.buildInfos[project.path];
  if (info === undefined) return "missing-buildinfo";

  for (const output of info.outputs) {
    if (snapshot.fileTimes[output] === undefined) return "missing-output";
  }

  for (const input of inputs) {
    const time = snapshot.fileTimes[input];
    // Deleted counts as changed: the output no longer matches reality.
    if (time === undefined || time > info.builtAt) return "stale-input";
  }

  for (const reference of project.references) {
    const referenced = snapshot.buildInfos[reference];
    if (referenced === undefined || referenced.builtAt > info.builtAt) {
      return "stale-reference";
    }
  }

  return "up-to-date";
}

