// v3tc05_project_references / ex4 - reference solution (author only).

export interface ProjectConfig {
  path: string;
  composite?: boolean;
  rootDir?: string;
  outDir?: string;
  files: readonly string[];
  references: readonly string[];
  imports: readonly string[];
}

export function validateProjects(projects: readonly ProjectConfig[]): string[] {
  const byPath = new Map(projects.map((project) => [project.path, project]));
  const found = new Set<string>();

  for (const project of projects) {
    const known = (target: string) => byPath.has(target);

    for (const reference of project.references) {
      const target = byPath.get(reference);
      if (target !== undefined && target.composite !== true) {
        found.add(
          `${project.path}: referenced project ${reference} must set composite: true`,
        );
      }
    }

    const referenced = new Set(project.references.filter(known));
    const imported = new Set(project.imports.filter(known));
    for (const target of imported) {
      if (!referenced.has(target)) {
        found.add(`${project.path}: missing reference to ${target}`);
      }
    }
    for (const target of referenced) {
      if (!imported.has(target)) {
        found.add(`${project.path}: unused reference to ${target}`);
      }
    }

    if (project.composite === true && project.outDir === undefined) {
      found.add(`${project.path}: outDir is required on a composite project`);
    }

    if (project.rootDir !== undefined) {
      for (const file of project.files) {
        if (!file.startsWith(project.rootDir)) {
          found.add(
            `${project.path}: file "${file}" is outside rootDir "${project.rootDir}"`,
          );
        }
      }
    }
  }

  return [...found].sort();
}

// v3tc05_project_references / ex5 - reference solution (author only).

function join(base: string, rest: string): string {
  return base === "" ? rest : `${base.replace(/\/$/, "")}/${rest}`;
}

export function resolvePaths(
  specifier: string,
  paths: Readonly<Record<string, readonly string[]>>,
  baseUrl: string,
  exists: (path: string) => boolean,
): string | null {
  const entries = Object.entries(paths);

  const exact = entries.find(
    ([key]) => !key.includes("*") && key === specifier,
  );
  let candidates: readonly string[] | undefined;

  if (exact !== undefined) {
    candidates = exact[1];
  } else {
    let bestPrefix = -1;
    let best: { targets: readonly string[]; captured: string } | undefined;
    for (const [key, targets] of entries) {
      const star = key.indexOf("*");
      if (star === -1) continue;
      const prefix = key.slice(0, star);
      const suffix = key.slice(star + 1);
      if (
        specifier.startsWith(prefix) &&
        specifier.endsWith(suffix) &&
        specifier.length >= prefix.length + suffix.length &&
        prefix.length > bestPrefix
      ) {
        bestPrefix = prefix.length;
        best = {
          targets,
          captured: specifier.slice(
            prefix.length,
            specifier.length - suffix.length,
          ),
        };
      }
    }
    if (best === undefined) return null;
    // Only the winning key is tried - there is no fallback to a shorter match.
    candidates = best.targets.map((target) =>
      target.replace("*", best.captured),
    );
  }

  for (const candidate of candidates) {
    const full = join(baseUrl, candidate);
    if (exists(full)) return full;
  }
  return null;
}

