exercises.hints:
## Hint 1

Memoised depth-first: the best path *ending at* a project is that project
appended to the best path ending at one of its references. Compute it once per
project and cache it, or an exponential graph will take exponential time.

## Hint 2

```ts
const best = new Map<string, CriticalPath>();
const compute = (path: string): CriticalPath => {
  const cached = best.get(path);
  if (cached) return cached;
  // ...visit references, pick the winner, append this project
};
```

The cache is also where the cycle detection goes: mark a project as in progress
before you recurse and throw if you reach one that is already in progress.

## Hint 3

The tie-break is a lexicographic array comparison, which is not the same as
comparing the joined strings — `["a", "b"]` versus `["ab"]` differ under one
and not the other. Write a small comparator that walks both arrays element by
element and treats the shorter one as smaller when it is a prefix.

Left to you: whether to compare candidate paths before or after appending the
current project. It gives the same answer here; work out why, because if it did
not, the two would be a genuinely subtle bug.

references.solution.ts:
// v3tc05_project_references / ex6 - reference solution (author only).

export interface Project {
  path: string;
  references: readonly string[];
}

export interface CriticalPath {
  length: number;
  path: string[];
}

function lexLess(a: readonly string[], b: readonly string[]): boolean {
  const shared = Math.min(a.length, b.length);
  for (let i = 0; i < shared; i += 1) {
    if (a[i] !== b[i]) return (a[i] as string) < (b[i] as string);
  }
  return a.length < b.length;
}

export function criticalPath(
  projects: readonly Project[],
  durations: Readonly<Record<string, number>>,
): CriticalPath {
  const byPath = new Map(projects.map((project) => [project.path, project]));
  const best = new Map<string, CriticalPath>();
  const open = new Set<string>();

  const compute = (path: string): CriticalPath => {
    const cached = best.get(path);
    if (cached !== undefined) return cached;
    if (open.has(path)) throw new Error("cycle detected");
    open.add(path);

    const project = byPath.get(path);
    let winner: CriticalPath = { length: 0, path: [] };
    for (const reference of [...(project?.references ?? [])].sort()) {
      if (!byPath.has(reference)) continue;
      const candidate = compute(reference);
      if (
        candidate.length > winner.length ||
        (candidate.length === winner.length && lexLess(candidate.path, winner.path))
      ) {
        winner = candidate;
      }
    }

    open.delete(path);
    const result: CriticalPath = {
      length: winner.length + (durations[path] ?? 0),
      path: [...winner.path, path],
    };
    best.set(path, result);
    return result;
  };

  let overall: CriticalPath = { length: 0, path: [] };
  for (const project of [...projects].sort((a, b) => (a.path < b.path ? -1 : 1))) {
    const candidate = compute(project.path);
    if (
      candidate.length > overall.length ||
      (candidate.length === overall.length && lexLess(candidate.path, overall.path))
    ) {
      overall = candidate;
    }
  }
  return overall;
}

