```

references.solution.ts:
// v3tc05_project_references / ex7 - reference solution (author only).

export interface Project {
  path: string;
  references: readonly string[];
}

export interface Assignment {
  project: string;
  worker: number;
  start: number;
  end: number;
}

export interface Schedule {
  makespan: number;
  assignments: Assignment[];
}

export function planParallelBuild(
  projects: readonly Project[],
  durations: Readonly<Record<string, number>>,
  workers: number,
): Schedule {
  if (!Number.isFinite(workers) || workers < 1) {
    throw new RangeError("workers must be at least 1");
  }

  const byPath = new Map(projects.map((project) => [project.path, project]));
  const pending = new Set(projects.map((project) => project.path));
  const finished = new Map<string, number>();
  const assignments: Assignment[] = [];
  let running: { project: string; worker: number; end: number }[] = [];
  let now = 0;

  const isReady = (path: string): boolean =>
    (byPath.get(path)?.references ?? []).every(
      (reference) =>
        !byPath.has(reference) || (finished.get(reference) ?? Infinity) <= now,
    );

  while (pending.size > 0 || running.length > 0) {
    const busy = new Set(running.map((entry) => entry.worker));
    const free: number[] = [];
    for (let worker = 0; worker < workers; worker += 1) {
      if (!busy.has(worker)) free.push(worker);
    }

    for (const path of [...pending].sort()) {
      if (free.length === 0) break;
      if (!isReady(path)) continue;
      const worker = free.shift() as number;
      const end = now + (durations[path] ?? 0);
      pending.delete(path);
      running.push({ project: path, worker, end });
      assignments.push({ project: path, worker, start: now, end });
    }

    if (running.length === 0) break;
    const nextTime = Math.min(...running.map((entry) => entry.end));
    for (const entry of running) {
      if (entry.end <= nextTime) finished.set(entry.project, entry.end);
    }
    running = running.filter((entry) => entry.end > nextTime);
    now = nextTime;
  }

  assignments.sort((a, b) => a.start - b.start || a.worker - b.worker);
  const makespan = assignments.reduce((max, a) => Math.max(max, a.end), 0);
  return { makespan, assignments };
}

