references.solution.ts:
// v3tc05_project_references / ex8 - reference solution (author only).

export interface RefProject {
  rootDir: string;
  outDir: string;
  sources: readonly string[];
  declarationMap: boolean;
  built: boolean;
}

export interface Resolved {
  file: string;
  kind: "source" | "declaration";
  goToDefinition: string;
}

const DECLARATION: Record<string, string> = {
  ".ts": ".d.ts",
  ".tsx": ".d.ts",
  ".mts": ".d.mts",
  ".cts": ".d.cts",
};

export function outputFor(project: RefProject, source: string): string | null {
  if (!project.sources.includes(source)) return null;
  if (!source.startsWith(project.rootDir)) return null;
  if (/\.d\.(ts|mts|cts)$/.test(source)) return null;

  const dot = source.lastIndexOf(".");
  const extension = dot === -1 ? "" : source.slice(dot);
  const output = DECLARATION[extension];
  if (output === undefined) return null;

  const relative = source
    .slice(project.rootDir.length)
    .replace(/^\//, "")
    .slice(0, -extension.length);
  return `${project.outDir.replace(/\/$/, "")}/${relative}${output}`;
}

export function sourceOfTruth(
  project: RefProject,
  source: string,
  options: { redirect: boolean },
): Resolved | null {
  const declaration = outputFor(project, source);
  if (declaration === null) return null;

  if (options.redirect) {
    // The editor's default: read sources, so no build is needed.
    return { file: source, kind: "source", goToDefinition: source };
  }
  if (!project.built) return null;
  return {
    file: declaration,
    kind: "declaration",
    goToDefinition: project.declarationMap ? source : declaration,
  };
}

