```

references.solution.ts:
// v3tc05_project_references / challenge - reference solution (author only).

export interface BuildProject {
  path: string;
  references: readonly string[];
  inputs: readonly string[];
  outputs: readonly string[];
  duration: number;
}

export interface World {
  fileTimes: Readonly<Record<string, number>>;
  builtAt: Readonly<Record<string, number>>;
}

export interface BuildPlan {
  order: string[];
  rebuilt: string[];
  skipped: string[];
  makespan: number;
  lines: string[];
}

function topologicalOrder(projects: readonly BuildProject[]): string[] {
  const byPath = new Map(projects.map((p) => [p.path, p]));
  const state = new Map<string, "open" | "closed">();
  const stack: string[] = [];
  const order: string[] = [];

  const visit = (path: string): void => {
    if (state.get(path) === "closed") return;
    if (state.get(path) === "open") {
      const cycle = [...stack.slice(stack.indexOf(path)), path];
      throw new Error(`cycle detected: ${cycle.join(" -> ")}`);
    }
    state.set(path, "open");
    stack.push(path);
    for (const reference of [...(byPath.get(path)?.references ?? [])].sort()) {
      if (byPath.has(reference)) visit(reference);
    }
    stack.pop();
    state.set(path, "closed");
    order.push(path);
  };

  for (const path of projects.map((p) => p.path).sort()) visit(path);
  return order;
}

export function planBuild(
  projects: readonly BuildProject[],
  world: World,
  workers: number,
): BuildPlan {
  if (!Number.isFinite(workers) || workers < 1) {
    throw new RangeError("workers must be at least 1");
  }

  const byPath = new Map(projects.map((p) => [p.path, p]));
  const order = topologicalOrder(projects);
  const rebuilding = new Set<string>();

  for (const path of order) {
    const project = byPath.get(path) as BuildProject;
    const builtAt = world.builtAt[path];
    let rebuild = builtAt === undefined;

    if (!rebuild) {
      for (const output of project.outputs) {
        if (world.fileTimes[output] === undefined) rebuild = true;
      }
      for (const input of project.inputs) {
        const time = world.fileTimes[input];
        if (time === undefined || time > (builtAt as number)) rebuild = true;
      }
      for (const reference of project.references) {
        if (!byPath.has(reference)) continue;
        if (rebuilding.has(reference)) rebuild = true;
        const referenceBuilt = world.builtAt[reference];
        if (referenceBuilt !== undefined && referenceBuilt > (builtAt as number)) {
          rebuild = true;
        }
      }
    }
    if (rebuild) rebuilding.add(path);
  }

  const rebuilt = order.filter((path) => rebuilding.has(path));
  const skipped = order.filter((path) => !rebuilding.has(path));

  // Schedule only the rebuilt set; everything else finished before we started.
  const pending = new Set(rebuilt);
  const finished = new Map<string, number>();
  let running: { project: string; worker: number; end: number }[] = [];
  let now = 0;
  let makespan = 0;

  while (pending.size > 0 || running.length > 0) {
    const busy = new Set(running.map((entry) => entry.worker));
    const free: number[] = [];
    for (let worker = 0; worker < workers; worker += 1) {
      if (!busy.has(worker)) free.push(worker);
    }

    for (const path of [...pending].sort()) {
      if (free.length === 0) break;
      const waits = (byPath.get(path)?.references ?? []).filter((reference) =>
        pending.has(reference) || running.some((r) => r.project === reference),
      );
      if (waits.length > 0) continue;
      const worker = free.shift() as number;
      const end = now + (byPath.get(path)?.duration ?? 0);
      pending.delete(path);
      running.push({ project: path, worker, end });
      makespan = Math.max(makespan, end);
    }

    if (running.length === 0) break;
    const nextTime = Math.min(...running.map((entry) => entry.end));
    for (const entry of running) {
      if (entry.end <= nextTime) finished.set(entry.project, entry.end);
    }
    running = running.filter((entry) => entry.end > nextTime);
    now = nextTime;
  }

  const lines = order.map(
    (path) => `${rebuilding.has(path) ? "BUILD" : "SKIP"} ${path}`,
  );
  lines.push(`MAKESPAN ${makespan}`);

  return { order, rebuilt, skipped, makespan, lines };
}

// v3tc05_project_references / review1 - reference solution (author only).

export type Cause =
  | "no-buildinfo"
  | "output-missing"
  | "config-changed"
  | "input-changed"
  | "reference-newer"
  | "none";

export interface Evidence {
  hasBuildInfo: boolean;
  missingOutputs: readonly string[];
  newestInput: number;
  builtAt: number;
  newestReference: number;
  configChangedAt: number;
}

export function diagnose(evidence: Evidence): {
  cause: Cause;
  explanation: string;
} {
  if (!evidence.hasBuildInfo) {
    return {
      cause: "no-buildinfo",
      explanation: "no .tsbuildinfo: this project has never been built here",
    };
  }
  if (evidence.missingOutputs.length > 0) {
    const first = [...evidence.missingOutputs].sort()[0] as string;
    return { cause: "output-missing", explanation: `output missing: ${first}` };
  }
  if (evidence.configChangedAt > evidence.builtAt) {
    return {
      cause: "config-changed",
      explanation: `tsconfig changed at ${evidence.configChangedAt}, after the last build at ${evidence.builtAt}`,
    };
  }
  if (evidence.newestInput > evidence.builtAt) {
    return {
      cause: "input-changed",
      explanation: `input newer than build: ${evidence.newestInput} > ${evidence.builtAt}`,
    };
  }
  if (evidence.newestReference > evidence.builtAt) {
    return {
      cause: "reference-newer",
      explanation: `a referenced project was rebuilt at ${evidence.newestReference}`,
    };
  }
  return { cause: "none", explanation: "up to date" };
}

// v3tc06_typecheck_performance / ex1 - reference solution (author only).

export function crossProductSize(sizes: readonly number[]): number {
  for (const size of sizes) {
    if (!Number.isInteger(size) || size < 0) {
      throw new RangeError("sizes must be non-negative integers");
    }
  }

  let product = 1;
  for (const size of sizes) {
    if (size === 0) return 0;
    // Check before multiplying: after overflow the value is already useless.
    if (product > Number.MAX_SAFE_INTEGER / size) return Infinity;
    product *= size;
  }
  return product;
}

export type Budget =
  | { ok: true; size: number }
  | { ok: false; size: number; limit: number };

export function checkTemplateUnion(
  parts: readonly number[],
  limit: number,
): Budget {
  const size = crossProductSize(parts);
  return size <= limit ? { ok: true, size } : { ok: false, size, limit };
}

// v3tc06_typecheck_performance / ex2 - reference solution (author only).

export type Equal<A, B> =
  (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2
    ? true
    : false;

export type Expect<T extends true> = T;

// Tail-recursive: the recursive call is the entire branch, so TypeScript
// applies its conditional-type tail-call optimisation.
export type Split<
  S extends string,
  D extends string,
  Acc extends string[] = [],
> = S extends `${infer Head}${D}${infer Rest}`
  ? Split<Rest, D, [...Acc, Head]>
  : [...Acc, S];

export function splitRuntime(source: string, delimiter: string): string[] {
  return source.split(delimiter);
}

export const TYPE_CHECKS: [
  Expect<Equal<Split<"a,b,c", ",">, ["a", "b", "c"]>>,
  Expect<Equal<Split<"a", ",">, ["a"]>>,
  Expect<Equal<Split<"", ",">, [""]>>,
  Expect<Equal<Split<"a,,b", ",">, ["a", "", "b"]>>,
  Expect<Equal<Split<"a-b", ",">, ["a-b"]>>,
] = [true, true, true, true, true];

// v3tc06_typecheck_performance / ex3 - reference solution (author only).

export function normalizeUnion(members: readonly string[]): string[] {
  const unique = new Set(members);
  if (unique.size === 0) return ["never"];
  if (unique.has("any")) return ["any"];
  if (unique.has("unknown")) return ["unknown"];
  unique.delete("never");
  if (unique.size === 0) return ["never"];
  return [...unique].sort();
}

export function unionRelationCost(
  source: readonly string[],
  target: readonly string[],
): number {
  let total = 0;
  for (const member of source) {
    const index = target.indexOf(member);
    total += index === -1 ? target.length : index + 1;
  }
  return total;
}

// v3tc06_typecheck_performance / ex4 - reference solution (author only).

export interface Module {
  path: string;
  imports: readonly string[];
  reexports: readonly string[];
}

export function isBarrel(module: Module): boolean {
  return module.reexports.length >= 2 && module.imports.length === 0;
}

export function fanOut(modules: readonly Module[], entry: string): number {
  const byPath = new Map(modules.map((module) => [module.path, module]));
  if (!byPath.has(entry)) return 0;

  const seen = new Set<string>([entry]);
  const queue = [entry];
  while (queue.length > 0) {
    const current = queue.shift() as string;
    const module = byPath.get(current);
    if (module === undefined) continue;
    for (const next of [...module.imports, ...module.reexports]) {
      if (!byPath.has(next) || seen.has(next)) continue;
      seen.add(next);
      queue.push(next);
    }
  }
  return seen.size - 1;
}

// v3tc06_typecheck_performance / ex5 - reference solution (author only).

export interface File {
  path: string;
  valueImports: readonly string[];
  typeImports: readonly string[];
}

export function programSize(
  files: readonly File[],
  entry: string,
  includeTypeOnly: boolean,
): number {
  const byPath = new Map(files.map((file) => [file.path, file]));
  if (!byPath.has(entry)) return 0;

  const seen = new Set<string>([entry]);
  const queue = [entry];
  while (queue.length > 0) {
    const current = queue.shift() as string;
    const file = byPath.get(current);
    if (file === undefined) continue;
    const edges = includeTypeOnly
      ? [...file.valueImports, ...file.typeImports]
      : file.valueImports;
    for (const next of edges) {
      if (!byPath.has(next) || seen.has(next)) continue;
      seen.add(next);
      queue.push(next);
    }
  }
  return seen.size;
}

export function typeOnlyWeight(files: readonly File[], entry: string): number {
  return programSize(files, entry, true) - programSize(files, entry, false);
}

