// v3tc06_typecheck_performance / ex6 - reference solution (author only).

export function parseDiagnostics(text: string): Record<string, number> {
  const result: Record<string, number> = {};

  for (const line of text.split("\n")) {
    const colon = line.indexOf(":");
    if (colon === -1) continue;

    const label = line.slice(0, colon);
    const words = label
      .toLowerCase()
      .split(/[^a-z0-9]+/)
      .filter((word) => word.length > 0);
    if (words.length === 0) continue;

    const key = words
      .map((word, index) =>
        index === 0 ? word : (word[0] as string).toUpperCase() + word.slice(1),
      )
      .join("");

    const value = Number.parseFloat(line.slice(colon + 1).replace(/,/g, ""));
    if (Number.isNaN(value)) continue;
    result[key] = value;
  }

  return result;
}

export interface TraceEvent {
  name: string;
  dur: number;
}

export interface Hotspot {
  name: string;
  total: number;
  count: number;
}

export function hotspots(
  events: readonly TraceEvent[],
  top: number,
): Hotspot[] {
  if (top <= 0) return [];
  const grouped = new Map<string, Hotspot>();
  for (const event of events) {
    const found = grouped.get(event.name);
    if (found === undefined) {
      grouped.set(event.name, { name: event.name, total: event.dur, count: 1 });
    } else {
      found.total += event.dur;
      found.count += 1;
    }
  }
  return [...grouped.values()]
    .sort((a, b) => b.total - a.total || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    .slice(0, top);
}

// v3tc06_typecheck_performance / ex7 - reference solution (author only).

const CHAIN = [
  "esnext",
  "es2023",
  "es2022",
  "es2021",
  "es2020",
  "es2019",
  "es2018",
  "es2017",
  "es2016",
  "es2015",
  "es5",
] as const;

const EXTRAS: Record<string, string[]> = {
  dom: ["lib.dom.d.ts"],
  "dom.iterable": ["lib.dom.iterable.d.ts", "lib.dom.d.ts"],
  webworker: ["lib.webworker.d.ts"],
};

function expand(name: string, into: Set<string>): void {
  const index = (CHAIN as readonly string[]).indexOf(name);
  if (index !== -1) {
    for (const version of CHAIN.slice(index)) into.add(`lib.${version}.d.ts`);
    return;
  }
  const extras = EXTRAS[name];
  if (extras === undefined) throw new Error(`unknown lib: ${name}`);
  for (const file of extras) into.add(file);
}

export function resolveLibFiles(
  target: string,
  lib: readonly string[] | undefined,
): string[] {
  const files = new Set<string>();

  if (lib === undefined) {
    expand(target, files);
    files.add("lib.dom.d.ts");
    files.add("lib.scripthost.d.ts");
  } else {
    for (const name of lib) expand(name, files);
  }

  // Checked on the assembled set, so dom.iterable's implicit dom counts.
  if (files.has("lib.dom.d.ts") && files.has("lib.webworker.d.ts")) {
    throw new Error("lib.dom.d.ts and lib.webworker.d.ts conflict");
  }

  return [...files].sort();
}

// v3tc06_typecheck_performance / ex8 - reference solution (author only).

export interface TypeNode {
  name: string;
  members: Readonly<Record<string, string>>;
}

export interface Checker {
  isAssignable(source: string, target: string): boolean;
  readonly comparisons: number;
}

const PRIMITIVES = new Set(["string", "number", "boolean"]);

export function createChecker(
  types: Readonly<Record<string, TypeNode>>,
): Checker {
  const results = new Map<string, boolean>();
  const inProgress = new Set<string>();
  let comparisons = 0;

  const lookup = (name: string): TypeNode => {
    const found = types[name];
    if (found === undefined) throw new Error(`unknown type: ${name}`);
    return found;
  };

  const isAssignable = (source: string, target: string): boolean => {
    if (source === "never" || source === "any") return true;
    if (target === "any" || target === "unknown") return true;
    if (PRIMITIVES.has(source) || PRIMITIVES.has(target)) {
      if (source !== target) {
        // Still validate the non-primitive side so typos are caught.
        if (!PRIMITIVES.has(source)) lookup(source);
        if (!PRIMITIVES.has(target)) lookup(target);
      }
      return source === target;
    }

    const key = `${source}->${target}`;
    const cached = results.get(key);
    if (cached !== undefined) return cached;
    // Already asking this question higher up the stack: assume yes.
    if (inProgress.has(key)) return true;

    inProgress.add(key);
    comparisons += 1;

    const from = lookup(source);
    const to = lookup(target);
    let related = true;
    for (const [member, memberType] of Object.entries(to.members)) {
      const own = from.members[member];
      if (own === undefined || !isAssignable(own, memberType)) {
        related = false;
        break;
      }
    }

    inProgress.delete(key);
    results.set(key, related);
    return related;
  };

  return {
    isAssignable,
    get comparisons() {
      return comparisons;
    },
  };
}

