## challenge — the triage report (moderate)

Edit `challenge/solution.ts`. You have the numbers. Now turn them into a
ranked list of things to do.

```ts
export interface Report {
  files: number;
  instantiations: number;
  checkTime: number;
  programTime: number;
  totalTime: number;
  libCheckEnabled: boolean;
  incremental: boolean;
  barrels: readonly { path: string; fanOut: number }[];
  slowTypes: readonly { name: string; total: number }[];
}

export type Severity = "high" | "medium" | "low";

export interface Finding {
  code: string;
  severity: Severity;
  message: string;
}

export function triage(report: Report): { findings: Finding[]; headline: string };
```

The rules, each producing zero or more findings:

- `skip-lib-check` / high — when `libCheckEnabled` is true and `files > 2000`:
  `skipLibCheck is off and the program has <files> files`
- `no-incremental` / high — when `incremental` is false:
  `incremental is off; every build is a cold build`
- `instantiation-blowup` / high — when `instantiations > 1000000`:
  `<instantiations> type instantiations; look for a recursive type`
- `io-bound` / medium — when `programTime > checkTime`:
  `program time <programTime>s exceeds check time <checkTime>s`
- `barrel` / medium — one per barrel whose `fanOut > 50`, in ascending path
  order: `barrel <path> pulls in <fanOut> modules`
- `slow-type` / low — one per entry of `slowTypes` whose `total >= 500`, in
  descending `total` order then ascending name:
  `<name> cost <total>ms of check time`
- `unaccounted` / low — when
  `totalTime - checkTime - programTime > totalTime * 0.3`:
  `<n>s is neither program nor check time`, where `<n>` is that difference
  rounded to one decimal place

`findings` is sorted by severity (`high`, then `medium`, then `low`), then by
`code` ascending, and within a code by the order the rule produced them.

`headline` is `check-bound: <checkTime>s checking` when
`checkTime >= programTime`, and `program-bound: <programTime>s building the
program` otherwise.

Example:

```ts
triage({
  files: 5000, instantiations: 200000, checkTime: 2, programTime: 6,
  totalTime: 9, libCheckEnabled: true, incremental: true,
  barrels: [{ path: "src/index.ts", fanOut: 300 }], slowTypes: [],
})
// findings: skip-lib-check (high), barrel (medium), io-bound (medium),
//           unaccounted (low)
// headline: "program-bound: 6s building the program"
```

Honest difficulty note: the rules are easy and the ordering is where the marks
are. Sorting by severity requires a rank, not a string comparison — `"high"`,
`"low"`, `"medium"` is alphabetical order and it is not the order you want.

```
uv run dojo test typescript v3tc06_typecheck_performance challenge
```

references.solution.ts:
// v3tc06_typecheck_performance / challenge - reference solution (author only).

export interface Report {
  files: number;
  instantiations: number;
  checkTime: number;
  programTime: number;
  totalTime: number;
  libCheckEnabled: boolean;
  incremental: boolean;
  barrels: readonly { path: string; fanOut: number }[];
  slowTypes: readonly { name: string; total: number }[];
}

export type Severity = "high" | "medium" | "low";

export interface Finding {
  code: string;
  severity: Severity;
  message: string;
}

const RANK: Record<Severity, number> = { high: 0, medium: 1, low: 2 };

export function triage(report: Report): {
  findings: Finding[];
  headline: string;
} {
  const findings: Finding[] = [];

  if (report.libCheckEnabled && report.files > 2000) {
    findings.push({
      code: "skip-lib-check",
      severity: "high",
      message: `skipLibCheck is off and the program has ${report.files} files`,
    });
  }
  if (!report.incremental) {
    findings.push({
      code: "no-incremental",
      severity: "high",
      message: "incremental is off; every build is a cold build",
    });
  }
  if (report.instantiations > 1000000) {
    findings.push({
      code: "instantiation-blowup",
      severity: "high",
      message: `${report.instantiations} type instantiations; look for a recursive type`,
    });
  }
  if (report.programTime > report.checkTime) {
    findings.push({
      code: "io-bound",
      severity: "medium",
      message: `program time ${report.programTime}s exceeds check time ${report.checkTime}s`,
    });
  }
  for (const barrel of [...report.barrels]
    .filter((entry) => entry.fanOut > 50)
    .sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))) {
    findings.push({
      code: "barrel",
      severity: "medium",
      message: `barrel ${barrel.path} pulls in ${barrel.fanOut} modules`,
    });
  }
  for (const slow of [...report.slowTypes]
    .filter((entry) => entry.total >= 500)
    .sort((a, b) => b.total - a.total || (a.name < b.name ? -1 : 1))) {
    findings.push({
      code: "slow-type",
      severity: "low",
      message: `${slow.name} cost ${slow.total}ms of check time`,
    });
  }
  const unaccounted = report.totalTime - report.checkTime - report.programTime;
  if (unaccounted > report.totalTime * 0.3) {
    findings.push({
      code: "unaccounted",
      severity: "low",
      message: `${Math.round(unaccounted * 10) / 10}s is neither program nor check time`,
    });
  }

  findings.sort(
    (a, b) =>
      RANK[a.severity] - RANK[b.severity] ||
      (a.code < b.code ? -1 : a.code > b.code ? 1 : 0),
  );

  const headline =
    report.checkTime >= report.programTime
      ? `check-bound: ${report.checkTime}s checking`
      : `program-bound: ${report.programTime}s building the program`;

  return { findings, headline };
}

// v3tc06_typecheck_performance / review1 - reference solution (author only).

export type Symptom =
  | "editor-slow-large-repo"
  | "cold-ci-build"
  | "one-file-slow"
  | "dts-emit-slow"
  | "watch-rebuilds-everything";

export interface Context {
  hasProjectReferences: boolean;
  incrementalCached: boolean;
  skipLibCheck: boolean;
  usesBarrels: boolean;
}

const answer = (fix: string, because: string) => ({ fix, because });

export function recommend(
  symptom: Symptom,
  context: Context,
): { fix: string; because: string } {
  switch (symptom) {
    case "editor-slow-large-repo":
      if (context.usesBarrels) {
        return answer(
          "import from modules, not barrels",
          "a barrel loads its whole graph for one symbol",
        );
      }
      if (!context.hasProjectReferences) {
        return answer(
          "split into referenced projects",
          "one program means every edit rechecks everything",
        );
      }
      return answer(
        "set disableSourceOfProjectReferenceRedirect",
        "the editor is reading sources of every referenced project",
      );

    case "cold-ci-build":
      if (!context.incrementalCached) {
        return answer(
          "cache .tsbuildinfo in CI",
          "without it every CI build is a first build",
        );
      }
      if (!context.skipLibCheck) {
        return answer(
          "turn on skipLibCheck",
          "node_modules declarations are being fully checked",
        );
      }
      return answer(
        "use a build cache keyed by input hashes",
        "the remaining work is genuine and should be reused across machines",
      );

    case "one-file-slow":
      return answer(
        "run tsc --generateTrace and read the hotspots",
        "a single slow file is almost always one expensive type",
      );

    case "dts-emit-slow":
      return answer(
        "annotate exported signatures, then consider isolatedDeclarations",
        "inferred public types must be computed before they can be written out",
      );

    case "watch-rebuilds-everything":
      if (context.usesBarrels) {
        return answer(
          "import from modules, not barrels",
          "a barrel makes every file a dependent of every other",
        );
      }
      return answer(
        "check that outputs are not inside the input glob",
        "emitting into a watched directory retriggers the watcher",
      );
  }
}

