```

references.solution.ts:
// v3tc07_publishing_types / ex1 - reference solution (author only).

export interface Declaration {
  name: string;
  exported: boolean;
  references: readonly string[];
}

export interface Surface {
  exported: string[];
  leaked: string[];
}

export function publicSurface(declarations: readonly Declaration[]): Surface {
  const byName = new Map(
    declarations.map((declaration) => [declaration.name, declaration]),
  );
  const exported = new Set(
    declarations.filter((d) => d.exported).map((d) => d.name),
  );

  const seen = new Set(exported);
  const queue = [...exported];
  while (queue.length > 0) {
    const current = queue.shift() as string;
    for (const reference of byName.get(current)?.references ?? []) {
      // Unknown names are built-ins or come from another package.
      if (!byName.has(reference) || seen.has(reference)) continue;
      seen.add(reference);
      queue.push(reference);
    }
  }

  return {
    exported: [...exported].sort(),
    leaked: [...seen].filter((name) => !exported.has(name)).sort(),
  };
}

