```

references.solution.ts:
// v3tc07_publishing_types / ex2 - reference solution (author only).

export type ApiItem =
  | { kind: "function"; name: string; signature: string }
  | {
      kind: "interface";
      name: string;
      members: readonly {
        name: string;
        type: string;
        optional: boolean;
        readonly: boolean;
      }[];
    }
  | { kind: "type"; name: string; definition: string }
  | { kind: "const"; name: string; type: string };

function assertNever(value: never): never {
  throw new Error(`unhandled item: ${JSON.stringify(value)}`);
}

function renderItem(item: ApiItem): string {
  switch (item.kind) {
    case "function":
      return `function ${item.name}${item.signature};`;
    case "type":
      return `type ${item.name} = ${item.definition};`;
    case "const":
      return `const ${item.name}: ${item.type};`;
    case "interface": {
      if (item.members.length === 0) return `interface ${item.name} {}`;
      const lines = [...item.members]
        .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
        .map(
          (member) =>
            `  ${member.readonly ? "readonly " : ""}${member.name}${
              member.optional ? "?" : ""
            }: ${member.type};`,
        );
      return [`interface ${item.name} {`, ...lines, "}"].join("\n");
    }
    default:
      return assertNever(item);
  }
}

export function renderApiReport(items: readonly ApiItem[]): string {
  if (items.length === 0) return "";
  return (
    [...items]
      .sort(
        (a, b) =>
          (a.name < b.name ? -1 : a.name > b.name ? 1 : 0) ||
          (a.kind < b.kind ? -1 : a.kind > b.kind ? 1 : 0),
      )
      .map(renderItem)
      .join("\n\n") + "\n"
  );
}

// v3tc07_publishing_types / ex3 - reference solution (author only).

export type Change =
  | { kind: "added"; name: string }
  | { kind: "removed"; name: string }
  | { kind: "changed"; name: string; before: string; after: string };

export type Bump = "major" | "minor" | "patch";

export function diffApi(
  before: Readonly<Record<string, string>>,
  after: Readonly<Record<string, string>>,
): Change[] {
  const names = [
    ...new Set([...Object.keys(before), ...Object.keys(after)]),
  ].sort();
  const changes: Change[] = [];

  for (const name of names) {
    const was = before[name];
    const now = after[name];
    if (was === undefined && now !== undefined) {
      changes.push({ kind: "added", name });
    } else if (was !== undefined && now === undefined) {
      changes.push({ kind: "removed", name });
    } else if (was !== undefined && now !== undefined && was !== now) {
      changes.push({ kind: "changed", name, before: was, after: now });
    }
  }
  return changes;
}

export function bumpFor(changes: readonly Change[]): Bump {
  if (changes.some((c) => c.kind === "removed" || c.kind === "changed")) {
    return "major";
  }
  if (changes.some((c) => c.kind === "added")) return "minor";
  return "patch";
}

export function nextVersion(current: string, bump: Bump): string {
  const parts = current.split(".");
  if (parts.length !== 3 || parts.some((p) => !/^\d+$/.test(p))) {
    throw new Error(`bad version: ${current}`);
  }
  const [major, minor, patch] = parts.map(Number) as [number, number, number];

  if (bump === "patch") return `${major}.${minor}.${patch + 1}`;
  // Under 0.x, the minor position carries breaking changes.
  if (bump === "minor" || major === 0) return `${major}.${minor + 1}.0`;
  return `${major + 1}.0.0`;
}

