```

references.solution.ts:
// v3tc07_publishing_types / ex4 - reference solution (author only).

export interface ExportedDecl {
  name: string;
  kind: "function" | "const" | "class";
  returnTypeAnnotated?: boolean;
  paramsAnnotated?: boolean;
  typeAnnotated?: boolean;
  initializerKind?: "literal" | "call" | "object" | "arrow";
  members?: readonly {
    name: string;
    annotated: boolean;
    visibility: "public" | "private";
  }[];
}

export function checkIsolatedDeclarations(
  decls: readonly ExportedDecl[],
): string[] {
  const found = new Set<string>();

  for (const decl of decls) {
    if (decl.kind === "function") {
      if (decl.returnTypeAnnotated !== true) {
        found.add(`${decl.name}: exported function needs an explicit return type`);
      }
      if (decl.paramsAnnotated !== true) {
        found.add(`${decl.name}: exported function needs parameter type annotations`);
      }
    }

    if (decl.kind === "const") {
      // A literal initializer is inferable from this file alone.
      if (decl.typeAnnotated !== true && decl.initializerKind !== "literal") {
        found.add(`${decl.name}: exported const needs a type annotation`);
      }
    }

    if (decl.kind === "class") {
      for (const member of decl.members ?? []) {
        if (member.visibility === "public" && member.annotated !== true) {
          found.add(
            `${decl.name}.${member.name}: public class member needs a type annotation`,
          );
        }
      }
    }
  }

  return [...found].sort();
}

