## Hint 1

Two booleans — has an input position, has an output position — plus one special
case for `"property"`, which sets both. Every rule in the prompt is a
combination of those, and the ordering falls out.

## Hint 2

```ts
let input = false;
let output = false;
for (const position of positions) {
  if (position === "return" || position === "readonly-property") output = true;
  if (position === "parameter") input = true;
  if (position === "property") { input = true; output = true; }
}
```

`"method-parameter"` deliberately sets neither, which is what makes rule 4
reachable.

## Hint 3

`annotationFor` is a lookup table, and writing it as
`Record<Variance, string>` gives you exhaustiveness for free: add a fifth
variance and the object stops compiling.

Left to you: whether an empty position list should really be bivariant. An
unused type parameter genuinely can vary either way — nothing depends on it —
so the answer is defensible, and it is also exactly what TypeScript infers.

references.solution.ts:
// v3tc07_publishing_types / ex5 - reference solution (author only).

export type Variance =
  | "covariant"
  | "contravariant"
  | "invariant"
  | "bivariant";

export type PositionKind =
  | "return"
  | "readonly-property"
  | "parameter"
  | "property"
  | "method-parameter";

export function varianceOf(positions: readonly PositionKind[]): Variance {
  let input = false;
  let output = false;

  for (const position of positions) {
    if (position === "return" || position === "readonly-property") {
      output = true;
    } else if (position === "parameter") {
      input = true;
    } else if (position === "property") {
      // Readable and writable, so both directions apply.
      input = true;
      output = true;
    }
    // "method-parameter" is checked bivariantly and contributes nothing.
  }

  if (input && output) return "invariant";
  if (output) return "covariant";
  if (input) return "contravariant";
  return "bivariant";
}

const ANNOTATIONS: Record<Variance, string> = {
  covariant: "out",
  contravariant: "in",
  invariant: "in out",
  bivariant: "",
};

export function annotationFor(variance: Variance): string {
  return ANNOTATIONS[variance];
}

// v3tc07_publishing_types / ex6 - reference solution (author only).

export type DeclKind =
  | "interface"
  | "namespace"
  | "class"
  | "function"
  | "type"
  | "enum"
  | "var";

export interface DeclarationEntry {
  name: string;
  kind: DeclKind;
}

export type MergeResult =
  | { ok: true; kinds: DeclKind[] }
  | { ok: false; reason: string };

export function mergeDeclarations(
  entries: readonly DeclarationEntry[],
): MergeResult {
  const count = (kind: DeclKind): number =>
    entries.filter((entry) => entry.kind === kind).length;

  if (count("type") > 0 && entries.length > 1) {
    return { ok: false, reason: "type aliases cannot merge" };
  }
  if (count("var") > 0 && entries.length > 1) {
    return { ok: false, reason: "duplicate identifier" };
  }
  if (count("class") > 1) {
    return { ok: false, reason: "duplicate class" };
  }

  if (count("namespace") > 0 && entries[0]?.kind === "namespace") {
    for (const kind of ["class", "function", "enum"] as const) {
      if (count(kind) > 0) {
        return { ok: false, reason: `namespace must be declared after ${kind}` };
      }
    }
  }

  const kinds = [...new Set(entries.map((entry) => entry.kind))].sort();
  return { ok: true, kinds };
}

