```

references.solution.ts:
// v3tc07_publishing_types / ex7 - reference solution (author only).

export interface BuildTargets {
  esm: boolean;
  cjs: boolean;
  subpaths: readonly string[];
}

export interface Manifest {
  type: "module";
  main?: string;
  module?: string;
  types?: string;
  exports: Record<string, unknown>;
  files: string[];
}

interface Paths {
  esmFile: string;
  esmTypes: string;
  cjsFile: string;
  cjsTypes: string;
}

function pathsFor(base: string): Paths {
  return {
    esmFile: `./dist/esm/${base}.mjs`,
    esmTypes: `./dist/esm/${base}.d.mts`,
    cjsFile: `./dist/cjs/${base}.cjs`,
    cjsTypes: `./dist/cjs/${base}.d.cts`,
  };
}

export function buildManifest(targets: BuildTargets): Manifest {
  if (!targets.esm && !targets.cjs) {
    throw new Error("at least one of esm or cjs is required");
  }
  for (const subpath of targets.subpaths) {
    if (!subpath.startsWith("./")) {
      throw new Error(`subpath must start with "./": ${subpath}`);
    }
  }

  const exports: Record<string, unknown> = {};
  for (const entryPoint of [".", ...targets.subpaths]) {
    const base = entryPoint === "." ? "index" : entryPoint.slice(2);
    const paths = pathsFor(base);
    // Insertion order is the resolution order; types first within each branch.
    const entry: Record<string, unknown> = {};
    if (targets.esm) {
      entry["import"] = { types: paths.esmTypes, default: paths.esmFile };
    }
    if (targets.cjs) {
      entry["require"] = { types: paths.cjsTypes, default: paths.cjsFile };
    }
    entry["default"] = targets.esm ? paths.esmFile : paths.cjsFile;
    exports[entryPoint] = entry;
  }
  exports["./package.json"] = "./package.json";

  const root = pathsFor("index");
  const manifest: Manifest = {
    type: "module",
    exports,
    files: ["dist"],
  };
  if (targets.cjs) manifest.main = root.cjsFile;
  if (targets.esm) manifest.module = root.esmFile;
  manifest.types = targets.esm ? root.esmTypes : root.cjsTypes;
  return manifest;
}

// v3tc07_publishing_types / ex8 - reference solution (author only).

export type AnyFn = (...args: never[]) => unknown;

export function deprecate<F extends AnyFn>(
  fn: F,
  message: string,
  warn?: (message: string) => void,
): F {
  let warned = false;
  const target = fn as unknown as (...args: unknown[]) => unknown;

  const wrapper = function (this: unknown, ...args: unknown[]): unknown {
    if (!warned) {
      warned = true;
      warn?.(message);
    }
    return target.apply(this, args);
  };

  // name and length are non-writable but configurable.
  Object.defineProperty(wrapper, "name", {
    value: fn.name,
    configurable: true,
  });
  Object.defineProperty(wrapper, "length", {
    value: fn.length,
    configurable: true,
  });

  // Same parameters, same return, same this: the wrapper really is an F.
  return wrapper as unknown as F;
}

export function deprecateProperty<T extends object, K extends keyof T>(
  target: T,
  key: K,
  message: string,
  warn?: (message: string) => void,
): void {
  const descriptor = Object.getOwnPropertyDescriptor(target, key);
  if (descriptor === undefined) {
    throw new Error(`no own property ${String(key)}`);
  }

  const value = descriptor.value as unknown;
  let warned = false;

  Object.defineProperty(target, key, {
    enumerable: descriptor.enumerable,
    configurable: descriptor.configurable,
    get() {
      if (!warned) {
        warned = true;
        warn?.(message);
      }
      return value;
    },
  });
}

