references.solution.ts:
// v3tc07_publishing_types / challenge - reference solution (author only).

export interface Declaration {
  name: string;
  exported: boolean;
  references: readonly string[];
}

export interface Candidate {
  declarations: readonly Declaration[];
  previousApi: Readonly<Record<string, string>>;
  currentApi: Readonly<Record<string, string>>;
  manifest: { exports?: unknown; types?: string; main?: string };
  currentVersion: string;
}

export interface Readiness {
  blockers: string[];
  warnings: string[];
  recommendedVersion: string;
}

function leakedTypes(declarations: readonly Declaration[]): string[] {
  const byName = new Map(declarations.map((d) => [d.name, d]));
  const exported = new Set(
    declarations.filter((d) => d.exported).map((d) => d.name),
  );
  const seen = new Set(exported);
  const queue = [...exported];
  while (queue.length > 0) {
    const current = queue.shift() as string;
    for (const reference of byName.get(current)?.references ?? []) {
      if (!byName.has(reference) || seen.has(reference)) continue;
      seen.add(reference);
      queue.push(reference);
    }
  }
  return [...seen].filter((name) => !exported.has(name)).sort();
}

function removedNames(
  before: Readonly<Record<string, string>>,
  after: Readonly<Record<string, string>>,
): string[] {
  return Object.keys(before)
    .filter((name) => after[name] === undefined)
    .sort();
}

function bumpFor(
  before: Readonly<Record<string, string>>,
  after: Readonly<Record<string, string>>,
): "major" | "minor" | "patch" {
  const names = new Set([...Object.keys(before), ...Object.keys(after)]);
  let added = false;
  for (const name of names) {
    const was = before[name];
    const now = after[name];
    if (was === undefined) added = true;
    else if (now === undefined || was !== now) return "major";
  }
  return added ? "minor" : "patch";
}

function nextVersion(
  current: string,
  bump: "major" | "minor" | "patch",
): string {
  const parts = current.split(".");
  if (parts.length !== 3 || parts.some((p) => !/^\d+$/.test(p))) {
    throw new Error(`bad version: ${current}`);
  }
  const [major, minor, patch] = parts.map(Number) as [number, number, number];
  if (bump === "patch") return `${major}.${minor}.${patch + 1}`;
  if (bump === "minor" || major === 0) return `${major}.${minor + 1}.0`;
  return `${major + 1}.0.0`;
}

export function checkRelease(candidate: Candidate): Readiness {
  const blockers = new Set<string>();
  const warnings = new Set<string>();

  for (const name of leakedTypes(candidate.declarations)) {
    blockers.add(`leaked type: ${name}`);
  }

  const exportsField = candidate.manifest.exports;
  if (
    typeof exportsField === "object" &&
    exportsField !== null &&
    !Array.isArray(exportsField)
  ) {
    const keys = Object.keys(exportsField as Record<string, unknown>);
    const isSubpathMap = keys.length > 0 && (keys[0] as string).startsWith(".");
    if (isSubpathMap) {
      if (!keys.includes(".")) blockers.add(`exports: missing "." entry`);
    } else if (keys.includes("types") && keys[0] !== "types") {
      blockers.add(`exports: "types" must be the first condition`);
    }
  }

  for (const name of removedNames(candidate.previousApi, candidate.currentApi)) {
    warnings.add(`removed export: ${name}`);
  }
  if (candidate.manifest.types === undefined && exportsField === undefined) {
    warnings.add("no types field and no exports map");
  }

  return {
    blockers: [...blockers].sort(),
    warnings: [...warnings].sort(),
    recommendedVersion: nextVersion(
      candidate.currentVersion,
      bumpFor(candidate.previousApi, candidate.currentApi),
    ),
  };
}

