// v3tc07_publishing_types / review1 - reference solution (author only).

export interface LegacyChatOptions {
  room: string;
  nickname?: string;
  onMessage?: (text: string) => void;
}

export interface LegacyChatInstance {
  send(text: string): void;
  close(): void;
}

export interface LegacyChatStatic {
  (options: LegacyChatOptions): LegacyChatInstance;
  new (options: LegacyChatOptions): LegacyChatInstance;
  readonly version: string;
  defaults: LegacyChatOptions;
}

export interface ChatHost {
  LegacyChat?: LegacyChatStatic;
}

declare global {
  // `var` is what puts a property on globalThis; let/const do not.
  var LegacyChat: LegacyChatStatic | undefined;
}

export function openChat(
  host: ChatHost,
  options: Partial<LegacyChatOptions> & { room: string },
): LegacyChatInstance {
  const chat = host.LegacyChat;
  if (chat === undefined) throw new Error("LegacyChat is not loaded");

  const merged: LegacyChatOptions = { ...chat.defaults };
  for (const [key, value] of Object.entries(options)) {
    // "not provided" and "provided as undefined" mean the same thing.
    if (value !== undefined) {
      (merged as Record<string, unknown>)[key] = value;
    }
  }
  return new chat(merged);
}
